        public ActionResult BCTienMat(DateTime FromDate, DateTime ToDate)
        {
            int RecNum = 10;
            int PageNum = 1;
            int toltalPage = 0;
            TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;

            DataTable dtbCash = _tkknService.BCNgayTienMat(ConnectionString, FromDate, ToDate);
            DataTable dtbExpenditure = _tkknService.BCNgayTienMatTU(ConnectionString, FromDate, ToDate);
            DataTable dtbOutSource = _tkknService.BCNgayTienMatGCN(ConnectionString, FromDate, ToDate);
            DataTable dtbTienMatTaiKet = _tkknService.BCNgayTienMatTienTaiKet(ConnectionString, FromDate, ToDate);

            ViewBag.TonDauTienMat = dtbTienMatTaiKet.Rows[0]["TonDauTienMat"];
            ViewBag.TonCuoiTienMat = dtbTienMatTaiKet.Rows[0]["TonCuoiTienMat"];
            ViewBag.TonDauQuyPhu = dtbTienMatTaiKet.Rows[0]["TonDauQuyPhu"];
            ViewBag.TonCuoiQuyPhu = dtbTienMatTaiKet.Rows[0]["TonCuoiQuyPhu"];
            ViewBag.TamUngBienNhanTay = dtbTienMatTaiKet.Rows[0]["TamUngBienNhanTay"];
            ViewBag.TienMatTaiKet = dtbTienMatTaiKet.Rows[0]["TienMatTaiKet"];

            ViewBag.PageNum = PageNum;
            ViewBag.RecNum = RecNum;
            ViewBag.TotalPage = toltalPage;
            ViewBag.ListExpenditure = dtbExpenditure;
            ViewBag.ListOutSource = dtbOutSource;
            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;

            return PartialView(dtbCash);
        }

        public ActionResult BCNganHang(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbBank = _tkknService.BCNgayNganHang(ConnectionString, FromDate, ToDate);
            DataTable tblNoNH = _tkknService.BCNgayNganHang_DanhSachNoVayNH(ConnectionString, FromDate, ToDate);
            TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            ViewBag.NoNH = tblNoNH;
            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            return PartialView(dtbBank);
        }

        public ActionResult BCXe(DateTime FromDate, DateTime ToDate)
        {

            DataTable dtbCash = _tkknService.BCNgayXe(ConnectionString, FromDate, ToDate);
            DataView dtvGXC = dtbCash.DefaultView;
            dtvGXC.RowFilter = "LoaiThanhToan = 'GIAO_XE_COC'";
            DataTable dtbGXC = dtvGXC.ToTable();

            DataView dtvGXN = dtbCash.DefaultView;
            dtvGXN.RowFilter = "LoaiThanhToan = 'GIAO_XE_NGAY'";
            DataTable dtbGXN = dtvGXN.ToTable();
            //Phần giao xe đại lý
            DataView dtvGXDL = dtbCash.DefaultView;
            dtvGXDL.RowFilter = "LoaiThanhToan = 'GIAO_XE_DAI_LY'";
            DataTable dtbGXDL = dtvGXDL.ToTable();
            //phần trao đổi xe
            DataView dtvTDX = dtbCash.DefaultView;
            dtvTDX.RowFilter = "LoaiThanhToan = 'TRAO_DOI_XE'";
            DataTable dtbTDX = dtvTDX.ToTable();
            //phần về TSCD
            DataView dtvTSCD = dtbCash.DefaultView;
            dtvTSCD.RowFilter = "LoaiThanhToan = 'TSCD'";
            DataTable dtbTSCD = dtvTSCD.ToTable();
            //phần về ONLINE
            DataView dtvOnline = dtbCash.DefaultView;
            dtvOnline.RowFilter = "LoaiThanhToan = 'ONLINE'";
            DataTable dtbOnline = dtvOnline.ToTable();
            //Giao xe cũ
            DataView dtvGiaoXeCu = dtbCash.DefaultView;
            dtvGiaoXeCu.RowFilter = "LoaiThanhToan = 'XE_CU'";
            DataTable dtbGiaoXeCu = dtvGiaoXeCu.ToTable();
            //Giao xe nội bộ
            DataView dtvGiaoNoiBo = dtbCash.DefaultView;
            dtvGiaoNoiBo.RowFilter = "LoaiThanhToan = 'GIAO_XE_NOI_BO'";
            DataTable dtGiaoNoiBo = dtvGiaoNoiBo.ToTable();

            //phan truc them kho xe
            DataTable dtbBCKhoXe = _tkknService.dtbBCKhoXe(ConnectionString, FromDate, ToDate);
            DataView dtvBCKhoXe = dtbBCKhoXe.DefaultView;
            DataTable dtbBCKhoXe_Total = dtvBCKhoXe.ToTable();
            //thu coc
            DataTable dtbThuCoc = _tkknService.dtbChiTraCoc(ConnectionString, FromDate, ToDate);
            DataView dtvThuCoc = dtbThuCoc.DefaultView;
            dtvThuCoc.RowFilter = "LoaiChiCoc = 'TraCoc'";
            DataTable dataThuCoc = dtvThuCoc.ToTable();

            //tra tien coc
            DataView dtvTraTienThua = dtbThuCoc.DefaultView;
            dtvTraTienThua.RowFilter = "LoaiChiCoc = 'TraTienThua'";
            DataTable dataTraTienThua = dtvTraTienThua.ToTable();
            //phan thu no
            DataTable dtbThuNo = _tkknService.dtbThuno(ConnectionString, FromDate, ToDate);
            DataView dtvThuNo = dtbThuNo.DefaultView;
            DataTable dataThuNo = dtvThuNo.ToTable();
            //thu giai ngan
            DataTable dtbThuGiaiNgan = _tkknService.dtbThuGiaiNgan(ConnectionString, FromDate, ToDate);
            DataView dtvGiaiNgan = dtbThuGiaiNgan.DefaultView;
            DataTable dataGiaiNgan = dtvGiaiNgan.ToTable();

            //XUẤT KM XE  GIAO
            DataTable dtbKMPKXeGiao = _tkknService.BCNgayXe_KMPKXeChuaGiao(ConnectionString, FromDate, ToDate);

            //XUẤT KM XE CHƯA GIAO
            DataView dtvKMPKXeChuaGiao = dtbKMPKXeGiao.DefaultView;
            dtvKMPKXeChuaGiao.RowFilter = "PhanLoaiXuatKM = 'KM_TL'";
            DataTable dtbKMPKXeChuaGiao = dtvKMPKXeChuaGiao.ToTable();

            //XUẤT KM XE ĐÃ GIAO
            DataView dtvKMPKXeDaGiao = dtbKMPKXeGiao.DefaultView;
            dtvKMPKXeDaGiao.RowFilter = "PhanLoaiXuatKM = 'KM_QK'";
            DataTable dtbKMPKXeDaGiao = dtvKMPKXeDaGiao.ToTable();

            //XUẤT KM HỨA TẶNG
            DataTable dtbKMPKPTHuaTang = _tkknService.BCKM_HuaTang_XE(FromDate, ToDate);

            DataView dtvKMPKHuaTangVuotKhung = dtbKMPKPTHuaTang.DefaultView;
            dtvKMPKHuaTangVuotKhung.RowFilter = "Loai = 'KM_HuaTang_VuotKhung'";
            DataTable dtbKMPKHuaTangVuotKhung = dtvKMPKHuaTangVuotKhung.ToTable();

            DataView dtvKMPKHuaTang = dtbKMPKPTHuaTang.DefaultView;
            dtvKMPKHuaTang.RowFilter = "Loai = 'KM_HuaTang'";
            DataTable dtbKMPKHuaTang = dtvKMPKHuaTang.ToTable();

            DataTable tblNoCoc = _tkknService.BCNgayXe_NoCoc(ConnectionString, FromDate, ToDate);
            if (tblNoCoc.Rows.Count == 0)
                tblNoCoc.Rows.Add(tblNoCoc.NewRow());
            DataRow r = tblNoCoc.Rows[0];
            ViewBag.Coc_NoDauKy = r["Coc_NoDauKy"];
            ViewBag.NoLe_DauKy = r["NoLe_DauKy"];
            ViewBag.NoNHBX_DauKy = r["NoNHBX_DauKy"];
            ViewBag.Coc_ThuTienMat = r["Coc_ThuTienMat"];
            ViewBag.NoLe_ThuTienMat = r["NoLe_ThuTienMat"];
            //ViewBag.TienMat = r["NoNHBX_ThuTienMat"];
            ViewBag.NoNHBX_ThuTienMat = r["NoNHBX_ThuTienMat"];
            ViewBag.Coc_ThuNganHang = r["Coc_ThuNganHang"];
            ViewBag.NoLe_ThuNganHang = r["NoLe_ThuNganHang"];
            ViewBag.NoNHBX_ThuNganHang = r["NoNHBX_ThuNganHang"];
            ViewBag.Coc_ChiCoc = r["Coc_ChiCoc"];
            ViewBag.NoLe_PhatSinh = r["NoLe_PhatSinh"];
            ViewBag.NoNHBX_PhatSinh = r["NoNHBX_PhatSinh"];
            ViewBag.Coc_NoCuoiKy = r["Coc_NoCuoiKy"];
            ViewBag.NoLe_CuoiKy = r["NoLe_CuoiKy"];
            ViewBag.NoNHBX_CuoiKy = r["NoNHBX_CuoiKy"];
            //phần về online
            ViewBag.NoOnline_DauKy = r["NoOnline_DauKy"];
            ViewBag.NoOnline_ThuTienMat = r["NoOnline_ThuTienMat"];
            ViewBag.NoOnline_ThuNganHang = r["NoOnline_ThuNganHang"];
            ViewBag.NoOnline_PhatSinh = r["NoOnline_PhatSinh"];
            ViewBag.NoOnline_CuoiKy = r["NoOnline_CuoiKy"];
            //Phần chuyển cọc 
            ViewBag.ChuyenCocBHTH = r["ChuyenCocBHTH"];
            ViewBag.SoTienSuDungCocBanXe = r["SoTienSuDungCocBanXe"];
            ViewBag.ChuyenCocGHBH = r["ChuyenCocGHBH"];
            ViewBag.ChuyenCocGTX = r["ChuyenCocGTX"];
            ViewBag.ChuyenCocTBDTK = r["ChuyenCocTBDTK"];
            ViewBag.ChuyenCocTHK = r["ChuyenCocTHK"];
            ViewBag.ChuyenCocTPHKI = r["ChuyenCocTPHKI"];
            ViewBag.SoTienHoanCoc = r["SoTienHoanCoc"];
            ViewBag.ChuyenCocTDIVU = r["ChuyenCocTDIVU"];

            ViewBag.ListGXC = dtbGXC;
            ViewBag.ListGXN = dtbGXN;
            ViewBag.ListGXDL = dtbGXDL;
            ViewBag.ListTDX = dtbTDX;
            ViewBag.ListTSCD = dtbTSCD;
            ViewBag.ListXOL = dtbOnline;
            ViewBag.ListXeCu = dtbGiaoXeCu;
            ViewBag.ListXeNoiBo = dtGiaoNoiBo;
            ViewBag.ListDXKhoXe = dtbBCKhoXe_Total;
            ViewBag.dataThuCoc = dataThuCoc;
            ViewBag.dataTraTienThua = dataTraTienThua;
            ViewBag.dataThuNo = dataThuNo;
            ViewBag.dataGiaiNgan = dataGiaiNgan;
            ViewBag.dataKMPKXeChuaGiao = dtbKMPKXeChuaGiao;
            ViewBag.dataKMPKXeDaGiao = dtbKMPKXeDaGiao;
            ViewBag.dataKMPKHuaTangVuotKhung = dtbKMPKHuaTangVuotKhung;
            ViewBag.dataKMPKHuaTang = dtbKMPKHuaTang;

            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            return PartialView();
        }

        public ActionResult BCPTDV(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbResult = _tkknService.BCNgayChiTietPhieuDichVu(ConnectionString, FromDate, ToDate);

            int count = dtbResult.Rows.Count;
            DataView dvResultDV = dtbResult.DefaultView;
            dvResultDV.RowFilter = "MaLoaiPhieu = 'TDIVU' AND LoaiBaoHiem <> 'XKG'";
            DataTable dtbDichVu = dvResultDV.ToTable();
            count = dtbDichVu.Rows.Count;

            //DataView dvResultPK = dtbResult.DefaultView;
            //dvResultPK.RowFilter = "MaLoaiPhieu = 'TPHKI'";
            //DataTable dtbPhuKien = dvResultPK.ToTable();

            //Phiếu Khuyến mãi
            DataView dvResultBL = dtbResult.DefaultView;
            dvResultBL.RowFilter = " PhanLoaiKM = 'KM_HT_OLD' ";//bỏ
            DataTable dtbPhuKienKM = dvResultBL.ToTable();
            //Phiếu bán lẻ
            DataView dvResultPK = dtbResult.DefaultView;
            dvResultPK.RowFilter = "MaLoaiPhieu = 'TPHKI' AND PhanLoaiKM = 'BL' AND LoaiKM = 'BL' ";
            DataTable dtbPhuKien = dvResultPK.ToTable();

            //Phiếu Khuyến mãi xe chưa xuất
            DataView dvResultKMChuaXuat = dtbResult.DefaultView;
            dvResultKMChuaXuat.RowFilter = "PhanLoaiKM = 'KM_TL' ";
            DataTable dtbResultKMChuaXuat = dvResultKMChuaXuat.ToTable();

            //Phiếu Khuyến mãi xe chưa xuất
            DataView dvResultKMDaXuat = dtbResult.DefaultView;
            dvResultKMDaXuat.RowFilter = "PhanLoaiKM = 'KM_QK' ";
            DataTable dtbResultKMDaXuat = dvResultKMDaXuat.ToTable();

            //Phiếu Khuyến mãi hứa tặng vượt khung
            DataView dvResultKMHuaTang_VK = dtbResult.DefaultView;
            dvResultKMHuaTang_VK.RowFilter = "PhanLoaiKM = 'KM_HuaTang_VK' ";
            DataTable dtbResultKMHuaTang_VK = dvResultKMHuaTang_VK.ToTable();

            //Phiếu Khuyến mãi hứa tặng vượt khung
            DataView dvResultKMHuaTang = dtbResult.DefaultView;
            dvResultKMHuaTang.RowFilter = "PhanLoaiKM = 'KM_HT' ";
            DataTable dtbResultKMHuaTang = dvResultKMHuaTang.ToTable();

            //DV XE CU TAN TRANG
            DataView dvResultDVTT = dtbResult.DefaultView;
            dvResultDVTT.RowFilter = "MaLoaiPhieu = 'TDIVU' AND LoaiBaoHiem = 'XKG'";
            DataTable dtbDichVuTT = dvResultDVTT.ToTable();
            ViewBag.dtbDichVuTT = dtbDichVuTT;
            DataTable dtbNoCoc = _tkknService.BCNgayChiTietPhieuDichVu_NoCoc(ConnectionString, FromDate, ToDate);
            DataRow dtr = dtbNoCoc.Rows[0];
            //bang 1
            ViewBag.NoCocDK = dtr["Coc_NoDauKy"];
            ViewBag.ThuTM = dtr["Coc_ThuTienMat"];
            ViewBag.ThuNH = dtr["Coc_ThuNganHang"];
            ViewBag.ChiCoc = dtr["Coc_ChiCoc"];
            ViewBag.NoCocCK = dtr["Coc_NoCuoiKy"];
            //bang 2
            ViewBag.NoLeDK = dtr["NoLe_DauKy"];
            ViewBag.PSNoLe = dtr["NoLe_PhatSinh"];
            ViewBag.ThuTMat = dtr["NoLe_ThuTienMat"];
            ViewBag.ThuNganHang = dtr["NoLe_ThuNganHang"];
            ViewBag.NoLeCK = dtr["NoLe_CuoiKy"];
            //Phần chuyển cọc 
            ViewBag.ChuyenCocBHTH = dtr["ChuyenCocBHTH"];
            ViewBag.SoTienSuDungCocDichVu = dtr["SoTienSuDungCocDichVu"];
            ViewBag.ChuyenCocGHBH = dtr["ChuyenCocGHBH"];
            ViewBag.ChuyenCocGTX = dtr["ChuyenCocGTX"];
            ViewBag.ChuyenCocTBDTK = dtr["ChuyenCocTBDTK"];
            ViewBag.ChuyenCocTHK = dtr["ChuyenCocTHK"];

            ViewBag.ChuyenCocTPHKI = dtr["ChuyenCocTPHKI"];
            ViewBag.SoTienHoanCoc = dtr["SoTienHoanCoc"];

            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            ViewBag.dtbDichVu = dtbDichVu;
            ViewBag.dtbDichVuTT = dtbDichVuTT;
            ViewBag.dtbPhuKien = dtbPhuKien;
            ViewBag.dtbPhuKienKM = dtbPhuKienKM;
            ViewBag.dtbResultKMChuaXuat = dtbResultKMChuaXuat;
            ViewBag.dtbResultKMDaXuat = dtbResultKMDaXuat;

            ViewBag.dtbResultKMHuaTang = dtbResultKMHuaTang;
            ViewBag.dtbResultKMHuaTang_VK = dtbResultKMHuaTang_VK;

            //bang 2
            ViewBag.NoLeDK_Hang = dtr["No_DauKy_Hang"];
            ViewBag.PSNoLe_Hang = dtr["No_PhatSinh_Hang"];
            ViewBag.ThuTMat_Hang = dtr["No_ThuTienMat_Hang"];
            ViewBag.ThuNganHang_Hang = dtr["No_ThuNganHang_Hang"];
            ViewBag.NoLeCK_Hang = dtr["No_CuoiKy_Hang"];

            TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            return PartialView();
        }
