        public ActionResult BCChiPhi(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbCashCosts = _tkknService.BCNgayChiPhiTM(ConnectionString, FromDate, ToDate);
            DataTable dtbBankCosts = _tkknService.BCNgayChiPhiNH(ConnectionString, FromDate, ToDate);
            DataTable dtbExtraFund = _tkknService.BCNgayChiPhiQuyPhu(ConnectionString, FromDate, ToDate);
            DataTable dtbFiveMillion = _tkknService.BCNgayChiPhiChiTren5Trieu(ConnectionString, FromDate, ToDate);
            DataTable dtbAdvanceHands = new DataTable(); //_tkknService.BCNgayChiPhiChiTamUngBienNhan(FromDate, ToDate);
            DataTable dtbAdvance = _tkknService.BCNgayChiPhiChiTamUng(ConnectionString, FromDate, ToDate);
            DataTable dtbChiPhiNCC = _tkknService.BCNgayChiPhi_NhaCungCap(ConnectionString, FromDate, ToDate);
            DataTable dtbChiPhiKH = _tkknService.BCNgayChiPhi_KhauHao(ConnectionString, FromDate, ToDate);
            DataTable dtdBDTK = _tkknService.BCNgayChiPhi_GoiBDTK(ConnectionString, FromDate, ToDate);
            DataTable dtCTCP = _tkknService.BCNgayChiPhiChiTiet(ConnectionString, FromDate, ToDate);
            DataTable dtPBCP = _tkknService.BCNgayPhanBoChiPhi(ConnectionString, FromDate, ToDate);
            DataTable dtCP_HHTX = _tkknService.BCNgay_ChiTietChiPhiHHTX(ConnectionString, FromDate, ToDate);
            //DataTable dtbChiPhiNCC_New = new DataTable(); || row["DoiTac"].ToString() == "PKD"
            double XangThuHo = 0, PKD = 0;
            int i = 0;
            while (i < dtbChiPhiNCC.Rows.Count)
            {
                if (dtbChiPhiNCC.Rows[i]["MaPhieuPhatSinh"].ToString().Contains("N2THK") && dtbChiPhiNCC.Rows[i]["DoiTac"].ToString() == "XangThuHo")
                {
                    XangThuHo += Convert.ToDouble(dtbChiPhiNCC.Rows[i]["Chi"].ToString());
                    dtbChiPhiNCC.Rows.Remove(dtbChiPhiNCC.Rows[i]);
                }
                else if (dtbChiPhiNCC.Rows[i]["MaPhieuPhatSinh"].ToString().Contains("N2THK") && dtbChiPhiNCC.Rows[i]["DoiTac"].ToString() == "PKD")
                {
                    PKD += Convert.ToDouble(dtbChiPhiNCC.Rows[i]["Chi"].ToString());
                    dtbChiPhiNCC.Rows.Remove(dtbChiPhiNCC.Rows[i]);
                }
                else
                {
                    i++;
                }
            }
            if (XangThuHo > 0)
            {
                DataRow rowXTH = dtbChiPhiNCC.NewRow();
                rowXTH["MaPhieuPhatSinh"] = "N2THK1808010001";
                rowXTH["DienGiai"] = "Xăng Thu Hộ";
                rowXTH["Thu"] = "0";
                rowXTH["Chi"] = XangThuHo;
                rowXTH["NguoiDuyet"] = "";
                rowXTH["TenNganHang"] = "VIETTINBANK.CK";
                rowXTH["DoiTac"] = "XangThuHo";
                dtbChiPhiNCC.Rows.Add(rowXTH);
            }
            if (PKD > 0)
            {
                DataRow rowPKD = dtbChiPhiNCC.NewRow();
                rowPKD["MaPhieuPhatSinh"] = "N2THK1808010002";
                rowPKD["DienGiai"] = "PKD";
                rowPKD["Thu"] = "0";
                rowPKD["Chi"] = PKD;
                rowPKD["NguoiDuyet"] = "";
                rowPKD["TenNganHang"] = "VIETTINBANK.CK";
                rowPKD["DoiTac"] = "PKD";
                dtbChiPhiNCC.Rows.Add(rowPKD);
            }


            ViewBag.ListBankCosts = dtbBankCosts;
            ViewBag.ListExtraFund = dtbExtraFund;
            ViewBag.ListFiveMillion = dtbFiveMillion;
            ViewBag.ListAdvanceHands = dtbAdvanceHands;
            ViewBag.ListAdvance = dtbAdvance;
            ViewBag.ListChiPhiNCC = dtbChiPhiNCC;
            ViewBag.ListGBDTK = dtdBDTK;
            ViewBag.ListCTCP = dtCTCP;
            ViewBag.ListPBCP = dtPBCP;
            ViewBag.ListChiPhiKH = dtbChiPhiKH;
            if (dtCP_HHTX.Rows.Count > 0)
            {
                dtCP_HHTX.Rows.RemoveAt(dtCP_HHTX.Rows.Count - 1);
            }
            ViewBag.ListCP_HHTX = dtCP_HHTX;
            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            return PartialView(dtbCashCosts);
        }

