                ttdkcbu = 0;
                nhapdkcbu = 0;
                nhapttcbu = 0;
                slxbcbu = 0;
                ttxbcbu = 0;
                slckcbu = 0;
                ttckcbu = 0;

            }

            demcbu = dtbCarInOut.Rows.Count;
