            {
                if (row["XuatXu"].ToString() == XuatXu)
                {
                    sldkcbu += Convert.ToDouble(row["SoLuongTonKhoDauKy"].ToString());
                    ttdkcbu += Convert.ToDouble(row["TongTienTonKhoDauKy"].ToString());
                    nhapdkcbu += Convert.ToDouble(row["SoLuongNhap"].ToString());
                    nhapttcbu += Convert.ToDouble(row["TongTienNhap"].ToString());
                    slxbcbu += Convert.ToDouble(row["SoLuongXuat"].ToString());
                    ttxbcbu += Convert.ToDouble(row["TongTienXuat"].ToString());
                    slckcbu += Convert.ToDouble(row["SoLuongTonKhoCuoiKy"].ToString());
                    ttckcbu += Convert.ToDouble(row["TongTienTonKhoCuoiKy"].ToString());
                }
            }
