            drCKD["TongTienTonKhoCuoiKy"] = ttckcbu;
            dtbCarInOut.Rows.InsertAt(drCKD, demcbu);


            foreach (DataRow row in (dtbCarInOut as DataTable).Rows)
            {
                if (row["TenModel"].ToString() != "Tổng CBU:" && row["TenModel"].ToString() != "Tổng CKD:")
                {
                    SoLuongTonKhoDauKy += row["SoLuongTonKhoDauKy"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongTonKhoDauKy"]);
                    TongTienTonKhoDauKy += row["TongTienTonKhoDauKy"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienTonKhoDauKy"]);
                    SoLuongNhap += row["SoLuongNhap"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongNhap"]);
                    TongTienNhap += row["TongTienNhap"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienNhap"]);
                    SoLuongXuat += row["SoLuongXuat"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongXuat"]);
                    TongTienXuat += row["TongTienXuat"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienXuat"]);
                    SoLuongTonKhoCuoiKy += row["SoLuongTonKhoCuoiKy"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongTonKhoCuoiKy"]);
                    TongTienTonKhoCuoiKy += row["TongTienTonKhoCuoiKy"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienTonKhoCuoiKy"]);
                    i++;
                }

                if (row["MaModel"].ToString() != str)
                {
                    DataRow dr = dtbCarInOut1.NewRow();
                    dr["TenModel"] = "Tổng Loại " + str;
                    dr["MaModel"] = "";
                    dr["TenMau"] = "";
                    dr["MaMau"] = "";
                    dr["XuatXu"] = "";
                    dr["GiaVon"] = 0;
                    dr["SoLuongTonKhoDauKy"] = SoLuongTonKhoDauKyXE;
                    dr["TongTienTonKhoDauKy"] = TongTienTonKhoDauKyXE;
                    dr["SoLuongNhap"] = SoLuongNhapXE;
                    dr["TongTienNhap"] = TongTienNhapXE;
