                    dr["TongTienXuat"] = TongTienXuatXE;
                    dr["SoLuongTonKhoCuoiKy"] = SoLuongTonKhoCuoiKyXE;
                    dr["TongTienTonKhoCuoiKy"] = TongTienTonKhoCuoiKyXE;
                    dtbCarInOut1.Rows.Add(dr);
                    SoLuongTonKhoDauKyXE = 0; TongTienTonKhoDauKyXE = 0
                           ; SoLuongNhapXE = 0; TongTienNhapXE = 0
                           ; SoLuongXuatXE = 0; TongTienXuatXE = 0
                           ; SoLuongTonKhoCuoiKyXE = 0; TongTienTonKhoCuoiKyXE = 0;
                }
                DataRow dr1 = dtbCarInOut1.NewRow();
                dr1["TenModel"] = row["TenModel"];
                dr1["MaModel"] = row["MaModel"];
                dr1["TenMau"] = row["TenMau"];
                dr1["MaMau"] = row["MaMau"];
                dr1["XuatXu"] = row["XuatXu"];
                dr1["GiaVon"] = row["GiaVon"];
