                SoLuongTonKhoDauKyXE += row["SoLuongTonKhoDauKy"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongTonKhoDauKy"]);
                TongTienTonKhoDauKyXE += row["TongTienTonKhoDauKy"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienTonKhoDauKy"]);
                SoLuongNhapXE += row["SoLuongNhap"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongNhap"]);
                TongTienNhapXE += row["TongTienNhap"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienNhap"]);
                SoLuongXuatXE += row["SoLuongXuat"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongXuat"]);
                TongTienXuatXE += row["TongTienXuat"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienXuat"]);
                SoLuongTonKhoCuoiKyXE += row["SoLuongTonKhoCuoiKy"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuongTonKhoCuoiKy"]);
                TongTienTonKhoCuoiKyXE += row["TongTienTonKhoCuoiKy"].ToString() == "" ? 0 : Convert.ToDouble(row["TongTienTonKhoCuoiKy"]);
                str = row["MaModel"].ToString();

            }

