            dr2["MaMau"] = "0";
            dr2["XuatXu"] = "0";
            dr2["GiaVon"] = 0;
            dr2["SoLuongTonKhoDauKy"] = SoLuongTonKhoDauKy;
            dr2["TongTienTonKhoDauKy"] = TongTienTonKhoDauKy;
