            dr2["TongTienNhap"] = TongTienNhap;
            dr2["SoLuongXuat"] = SoLuongXuat;
            dr2["TongTienXuat"] = TongTienXuat;
            dr2["SoLuongTonKhoCuoiKy"] = SoLuongTonKhoCuoiKy;
            dr2["TongTienTonKhoCuoiKy"] = TongTienTonKhoCuoiKy;
            dtbCarInOut1.Rows.Add(dr2);

            foreach (DataRow row in (dtbCarInOut1 as DataTable).Rows)
            {
                if (row["TenModel"].ToString() == "Tổng Loại " || row["TenModel"].ToString() == "Tổng Loại")
                {
                    dtbCarInOut1.Rows.Remove(row);
                    break;
                }
            }
            foreach (DataRow row in (dtbCarInOut1 as DataTable).Rows)
            {
                if (row["TenModel"].ToString() == "Tổng Loại " || row["TenModel"].ToString() == "Tổng Loại")
                {
                    dtbCarInOut1.Rows.Remove(row);
                    break;
                }
            }

            #endregion XeXNT
            ViewBag.dtbCarInOut1 = dtbCarInOut1;
