        public ActionResult BCCongNoKhac(DateTime FromDate, DateTime ToDate)
        {
            //DataTable DebtCollection = _tkknService.BCNoTHBH(FromDate, ToDate);
            //DataTable Promotioninsurance = _tkknService.BCNoBHKM(FromDate, ToDate);
            //DataTable NoHHBH = _tkknService.BCNoHHBH(FromDate, ToDate);
            DataTable dtResult = _tkknService.BCCongNoKhac(ConnectionString, FromDate, ToDate);
            //Nợ phải thu khác
            DataView dvNPTK = dtResult.DefaultView;
            dvNPTK.RowFilter = "LoaiNo = 'NoThuKhac'";
            DataTable dtbNPTK = dvNPTK.ToTable();
            //Nợ phải trả khác
            DataView dvNPTRK = dtResult.DefaultView;
            dvNPTRK.RowFilter = "LoaiNo = 'NoTraKhac'";
            DataTable dtbNPTRK = dvNPTRK.ToTable();
            //Nợ thu vay mượn ngắn hạn
            DataView dvNTVV = dtResult.DefaultView;
            dvNTVV.RowFilter = "LoaiNo = 'NoThuVayMuon' and LoaiBaoHiem ='NH'";
            DataTable dtbNTVV = dvNTVV.ToTable();
            //Nợ thu vay mượn dài hạn
            DataView dvNTVV_DaiHan = dtResult.DefaultView;
            dvNTVV_DaiHan.RowFilter = "LoaiNo = 'NoThuVayMuon' and LoaiBaoHiem ='DH'";
            DataTable dtbNTVV_DaiHan = dvNTVV_DaiHan.ToTable();
            //Nợ trả vay mượn
            DataView dvNTVM = dtResult.DefaultView;
            dvNTVM.RowFilter = "LoaiNo = 'NoTraVayMuon' and LoaiBaoHiem ='NH'";
            DataTable dtbNTVM = dvNTVM.ToTable();
            //Nợ trả vay mượn dài hạn
            DataView dvNTVM_DaiHan = dtResult.DefaultView;
            dvNTVM_DaiHan.RowFilter = "LoaiNo = 'NoTraVayMuon' and LoaiBaoHiem ='DH'";
            DataTable dtbNTVM_DaiHan = dvNTVM_DaiHan.ToTable();
            //Nợ phải thu giấy tờ xe
            DataView dvNPTGTX = dtResult.DefaultView;
            dvNPTGTX.RowFilter = "LoaiNo = 'GiayToXe'";
            DataTable dtbNPTGTX = dvNPTGTX.ToTable();
            //Nợ thu hộ khác
            DataView dvNPTNTHK = dtResult.DefaultView;
            dvNPTNTHK.RowFilter = "LoaiNo = 'NoThuHoKhac'";
            DataTable dtbNPTNTHK = dvNPTNTHK.ToTable();


            ViewBag.ToDate = ToDate;
            ViewBag.FromDate = FromDate;
            ViewBag.dtbNPTK = dtbNPTK;
            ViewBag.dtbNPTRK = dtbNPTRK;
            ViewBag.dtbNTVV = dtbNTVV;
            ViewBag.dtbNTVV_DaiHan = dtbNTVV_DaiHan;
            ViewBag.dtbNTVM = dtbNTVM;
            ViewBag.dtbNTVM_DaiHan = dtbNTVM_DaiHan;
            ViewBag.dtbNPTGTX = dtbNPTGTX;
            ViewBag.dtbNPTNTHK = dtbNPTNTHK;
            TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            return PartialView();
        }
