        public ActionResult CongNo(string FromDate = "", string ToDate = "", string query = "", int p = 1, string export = "")
        {
            DateTime f = new DateTime(), t = new DateTime();
            SetSearch(ref FromDate, ref ToDate, ref f, ref t, p, ref query, "ReportCongNo");
            string html = "";
            if (export == "Excel")
            {
                html = ExportExcelCongNo(f, t);
            }
            else
            {
                html = ExportHtmlCongNo(f, t);
            }
            return Content(html);
        }
