        public string ExportHtmlCongNo(DateTime from, DateTime to)
        {
            var data = _tkknService.GetReportCongNo(from, to, 1, ref total, 65000);
            string html = @"<div class='x_content'>
                <div class='table-responsive'>
                <table style='border:1px solid black; border-collapse:collapse;width:100%'>";
            html += "<tr><td  colspan='12' style='text-align:center;border:1px solid black;'>BẢNG ĐỐI CHIẾU CÔNG NỢ MUA PHỤ KIỆN ĐỂ KHUYẾN MÃI VÀ BÁN CHO KHÁCH HÀNG</td></tr>";
            html += "<tr><td colspan='12' style='text-align:center;border:1px solid black;'>Từ ngày: " + from.ToString("dd/MM/yyyy") + " Đến ngày: " + to.ToString("dd/MM/yyyy") + " </td></tr>";
            html += "<tr style='background:#daeef3'> <td style='border:1px solid #000000'>STT</td> <td style='border:1px solid #000000'>Tên khách hàng</td> <td style='border:1px solid #000000'>Hợp đồng</td> <td style='border:1px solid #000000'>Ngày xuất</td> <td style='border:1px solid #000000'>Phiếu xuất </td> <td style='border:1px solid #000000'>Loại xe</td> <td style='border:1px solid #000000'>Số khung/Biển số</td> <td style='border:1px solid #000000'>Tên hàng</td> <td style='border:1px solid #000000'>Giá nhà cung cấp</td> <td style='border:1px solid #000000'>Tổng cộng</td> <td style='border:1px solid #000000'>Nhà cung cấp</td> <td style='border:1px solid #000000'>Ghi chú</td></tr>";
            for (int i = 0; i < data.Count; i++)
            {
                var item = data[i];
                int count = 1;
                double total = 0;
                string first = "";
                string next = "";
                string loaixe = "";
                List<ViewChiTietKhuyenMai> CTKM = new List<ViewChiTietKhuyenMai>();
                List<ChiTietBanPhuKien> CTBPK = new List<ChiTietBanPhuKien>();
                PhieuThu tpk = new PhieuThu();
                if (item.MaLoaiPhieu == "TPHKI")
                {
                    CTBPK = _CTBPKService.GetBySoHopDong(item.SoHopDong);
                    count = CTBPK.Count;
                }
                else
                {
                    var temp = _ctkmService.GetCTKM(item.MaPhieuThu);
                    CTKM = _ctkmService.GetCTKM(item.MaPhieuThu).Where(x => x.NguonKhuyenMai != null && x.NguonKhuyenMai.ToUpper().Contains("KHO_PK")).ToList();
                    CTBPK = _CTBPKService.GetBySoHopDong(item.SoHopDong);
                    tpk = _phieuThuService.GetPhieuThuTDIVUBySoDichVu(item.SoHopDong);
                    if (tpk != null)
                    {
                        CategoryItem iLoaiXe = _categoryService.Get(int.Parse(tpk.LoaiXe));
                        if (iLoaiXe != null)
                            loaixe = iLoaiXe.Name;
                        else
                            loaixe = tpk.LoaiXe;
                    }
                    if (CTKM.Count > 0)
                    {
                        count += CTKM.Count + 1;
                    }
                    if (CTBPK.Count > 0)
                    {
                        count += CTBPK.Count + 1;
                    }
                    if (count > 1)
                        count--;
                }
                html += "<tr>";
                html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + (i + 1) + "</td>";
                html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + item.HoTen + "</td>";
                html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + item.SoHopDong + "</td>";
                html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + item.NgayThu + "</td>";
                html += "<td style='border:1px solid #000000' rowspan='" + count + "'></td>";
                html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + loaixe + "</td>";
                html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + item.SoKhung + "</td>";
                if (item.MaLoaiPhieu == "TPHKI")
                {
                    if (CTBPK.Count == 0)
                    {
                        next += " <td style='border:1px solid #000000'></td>";
                        next += " <td style='border:1px solid #000000'></td>";
                    }
                    else
                    {
                        for (int j = 0; j < CTBPK.Count; j++)
                        {
                            var obj = CTBPK[j];
                            total += Convert.ToDouble(obj.GiaVon == null ? "0" : obj.GiaVon.ToString());
                            if (j == 0)
                            {
                                first += " <td style='border:1px solid #000000'>" + obj.TenHang + "</td>";
                                first += " <td style='border:1px solid #000000'>" + obj.GiaVon + "</td>";
                            }
                            else
                            {
                                next += "<tr>";
                                next += " <td style='border:1px solid #000000'>" + obj.TenHang + "</td>";
                                next += " <td style='border:1px solid #000000'>" + obj.GiaVon + "</td>";
                                next += "</tr>";
                            }
                        }
                    }
                    html += first;
                    html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + total + "</td>";
                    html += "<td style='border:1px solid #000000' rowspan='" + count + "'></td>";
                    html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + item.GhiChu + "</td>";
                    html += next;

                }
                else
                {
                    if (CTKM.Count > 0)
                    {
                        html += "<td colspan='2' style='text-align:center;border:1px solid #000000;background:#ffff00'>Khuyến mãi</td>";
                        var listNKM = _ctkmService.GetNKM();
                        for (int j = 0; j < CTKM.Count; j++)
                        {
                            var obj = CTKM[j];
                            total += obj.GiaVon;
                            next += "<tr>";
                            next += " <td style='border:1px solid #000000'>" + obj.NoiDung + "</td>";
                            next += " <td style='border:1px solid #000000'>" + obj.GiaVon + "</td>";
                            next += "</tr>";
                        }

                    }
                    if (CTBPK.Count > 0)
                    {
                        if (CTKM.Count != 0)
                        {
                            next += "<tr><td colspan='2' style='text-align:center;border:1px solid #000000;background:#ffff00'>Hàng bán</td></tr>";
                        }
                        else
                        {
                            html += "<td colspan='2' style='text-align:center;border:1px solid #000000;background:#ffff00'>Hàng bán</td>";
                        }
                        for (int j = 0; j < CTBPK.Count; j++)
                        {
                            var obj = CTBPK[j];
                            total += obj.GiaVon;
                            next += "<tr>";
                            next += " <td style='border:1px solid #000000'>" + obj.TenHang + "</td>";
                            next += " <td style='border:1px solid #000000'>" + obj.GiaVon + "</td>";
                            next += "</tr>";
                        }
                    }
                    html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + total + "</td>";
                    html += "<td style='border:1px solid #000000' rowspan='" + count + "'></td>";
                    html += "<td style='border:1px solid #000000' rowspan='" + count + "'>" + item.GhiChu + "</td>";
                    html += next;
                }
                html += "</tr>";
            }
            html += "</table></div></div>";
            return html;
        }

        public string ExportExcelCongNo(DateTime from, DateTime to)
        {
            Response.ClearContent();
            Response.Buffer = true;
            string fname = "baocaocongno_" + DateTime.Now.ToString("dd/MM/yyyy");
            Response.AddHeader("content-disposition", "attachment; filename=" + fname + ".xls");
            Response.ContentType = "application/ms-excel";
            Response.ContentEncoding = System.Text.Encoding.Unicode;
            Response.BinaryWrite(System.Text.Encoding.Unicode.GetPreamble());
            //render data 
            var html = ExportHtmlCongNo(from, to);
            Response.Output.Write(html);
            Response.Flush();
            Response.End();
            return html;
        }
        public ActionResult ReportAll(DateTime FromDate, DateTime ToDate)
        {
            _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportAll");
            _log4net.Param("FromDate", FromDate);
            _log4net.Param("ToDate", ToDate);
            _log4net.Param("ShowRoom", ShowRoom);
            string session = TNK.Core.Common.GenerateRandomString(6);
            DateTime startTime = DateTime.Now;
            try
            {
                DateTime dateHide = new DateTime(2025, 3, 1);
                string[] listHideReport = { "DT PT&DV", "Kho PT (2)" };
                var reports = _tkknService.GetReportLists(ConnectionString, CurrentUser.UserId);
                this.FromDate = FromDate;
                this.ToDate = ToDate;
                //var str = CacheKey.keyExcelTotal
                TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
                TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                DenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;

                string str = Server.MapPath("~\\Views\\FileMau\\Template_BaoCaoNgay.xlsx");
                FileInfo template = new FileInfo(str);
                pck = new ExcelPackage(new FileInfo(str));


                string strFileName = ShowRoom + "-" + session + "-Bao cao thu chi " + FromDate.ToString("dd.MM.yyyy") + "_" + ToDate.ToString("dd.MM.yyyy") + "-" + DateTime.Now.ToString("hhMMssfff") + ".xlsx";
                var sheetNames = pck.Workbook.Worksheets.Select(s => s.Name).ToList();
                var sheetonRole = reports.Select(s => s.SheetName).ToList();
                sheetonRole.Add("Report");
                var diff = sheetNames.Except(sheetonRole).ToList();
                //if (FromDate >= dateHide)
                //{
                //    // Chỉ giữ lại các sheet có trong sheetonRole và không thuộc listHideReport
                //    diff.AddRange(listHideReport);
                //    reports = reports.Where(rep => !listHideReport.Contains(rep.SheetName)).ToList();
                //}

                //foreach (var i in diff)
                //{
                //    var sheet = pck.Workbook.Worksheets[i];
                //    sheet.Hidden = eWorkSheetHidden.Hidden;
                //}


                foreach (var report in reports)
                {
                    try
                    {
                        if (FromDate >= report.ExpirDate && report.ExpirDate != null)
                        {
                            // Chỉ giữ lại các sheet có trong sheetonRole và không thuộc listHideReport
                            diff.Add(report.SheetName);
                            reports = reports.Where(rep => !listHideReport.Contains(rep.SheetName)).ToList();
                        }
                        _log4net.Start(report.ReportName);
                        DateTime startDate = DateTime.Now;
                        Type thisType = this.GetType();
                        var theMethod = thisType
                                .GetMethod(report.Method, System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.Public);
                        theMethod.Invoke(this, null);
                        WriteLog("Report", report.Method, "", session, startDate, DateTime.Now);
                        _log4net.End(report.ReportName);
                    }
                    catch (Exception ex)
                    {
                        _log4net.Param("ReportName", report.ReportName);
                        _log4net.Param("SheetName", report.SheetName);
                        _log4net.Param("Method", report.Method);
                        _log4net.Error(ex);
                        if (ex.InnerException != null)
                            _log4net.Error(ex.InnerException);
                        if (ex.StackTrace != null)
                            _log4net.Error(ex.StackTrace);
                        _log4net.End(report.ReportName);
                    }
                }
                foreach (var i in diff)
                {
                    var sheet = pck.Workbook.Worksheets[i];
                    sheet.Hidden = eWorkSheetHidden.Hidden;
                }
                WriteLog("Report", "ReportAll_Database('" + FromDate.ToString("yyyy/MM/dd") + "','" + ToDate.ToString("yyyy/MM/dd") + " ')", "", session, startTime, DateTime.Now);

                DateTime endTime = DateTime.Now;

                pck.Workbook.Worksheets["Report"].Select("A1");
                pck.Workbook.Worksheets["Report"].Cells["C2"].Value = ShowRoom;
                pck.Workbook.Worksheets["Report"].Cells["C3"].Value = FromDate;
                pck.Workbook.Worksheets["Report"].Cells["C4"].Value = ToDate;
                pck.Workbook.Worksheets["Report"].Cells["C5"].Value = CurrentUser.UserName;
                pck.Workbook.Worksheets["Report"].Cells["C6"].Value = startTime;
                pck.Workbook.Worksheets["Report"].Cells["C7"].Value = endTime;
                pck.Workbook.Worksheets["Report"].Cells["C8"].Value = endTime.Subtract(startTime).TotalSeconds / 60.0;

                WriteLog("Report", "ReportAll_AfterSaveFile('" + FromDate.ToString("yyyy/MM/dd") + "','" + ToDate.ToString("yyyy/MM/dd") + " ')", "", session, startTime, DateTime.Now);
                this.AddActionLog(CurrentUser.UserName, "Report", "ReportAll_WebComplete", startTime, endTime, "");
                //ExcelPackage pckResult = new ExcelPackage(pck.Stream);//(new FileInfo(Server.MapPath("~\\EXIM\\EX") + "\\" + strFileName));                
                //try
                //{

                //    pck.SaveAs(new FileInfo(Server.MapPath("~\\EXIM\\EX") + "\\" + strFileName));                  
                //    pck.Dispose();

                //}
                //catch (Exception exx)
                //{
                //    _log4net.Error(exx);
                //}
                _log4net.End("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportAll");

                return new ExcelInsuranceDownload(pck, strFileName);
            }
            catch (Exception ex)
            {
                this.AddActionLog(CurrentUser.UserName, "Report", "ReportAll", DateTime.Now, DateTime.Now, ex.ToString());
                _log4net.Error(ex);
            }
            _log4net.End("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportAll");
            this.SummitActionLogToDatabase();
            return View();
        }

