        private void FormatReportXe(ref ExcelWorksheet sheet, ref int index, DataTable tbl, string[] col, string STT, string TieuDe
            , ref double TotalTienNganHangBan, ref double TotalNoVayNganHangBan, ref double TotalNoNoLeBan, ref double TotalCaTheBan, ref double TotalChiCocBan
            , ref double TotalGiaVonBan, ref double TotalLoiNhuanTruocKMBan, ref double TotalKMQuaTangBan, ref double TotalKMPhiTruocBaBan
            , ref double TotalKMKhacBan, ref double TotalKMPhuKienBan, ref double TotalKMPhuTungBan, ref double TotalKMDongSonBan
            , ref double TotalKMBaoHiemBan, ref double TotalKMHoaHongBan, ref double TotalKMBaoDuongBan
            , ref double TotalChietKhauThuongMaiBan
            , ref double TotalLoiNhuanSauChietKhauBan
            , ref double TotalLoiNhuanBan
            , ref double TotalKM_GHBHBan
            , ref double TotalSoLuongBan,
ref double TotalGiaNiemYetBan,
ref double TotalGiamGiaBan,
ref double TotalGiaBanBan,
ref double TotalTienMatBan
            )
        {

            sheet.Cells["A" + index].Value = STT;
            sheet.Cells["A" + index].Merge = true;
            sheet.Cells["A" + index].Style.Fill.PatternType = ExcelFillStyle.Solid;
            sheet.Cells["A" + index].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Aqua);
            sheet.Cells["A" + index].Style.Font.Bold = true;
            sheet.Cells["A" + index].Style.VerticalAlignment = ExcelVerticalAlignment.Center;
            sheet.Cells["A" + index].Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            sheet.Cells["A" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
            sheet.Cells["A" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

            #region GIAO XE CỌC
            sheet.Cells["B" + index + ":AO" + index].Value = TieuDe;
            sheet.Cells["B" + index + ":AO" + index].Merge = true;
            sheet.Cells["B" + index + ":AO" + index].Style.Fill.PatternType = ExcelFillStyle.Solid;
            sheet.Cells["B" + index + ":AO" + index].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Aqua);
            sheet.Cells["B" + index + ":AO" + index].Style.Font.Bold = true;
            sheet.Cells["B" + index + ":AO" + index].Style.VerticalAlignment = ExcelVerticalAlignment.Center;
            sheet.Cells["B" + index + ":AO" + index].Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
            sheet.Cells["B" + index + ":AO" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
            sheet.Cells["B" + index + ":AO" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

            //sheet.Cells["C" + index + ":AO" + index].Value = "";
            //sheet.Cells["C" + index + ":AO" + index].Merge = true;
            //sheet.Cells["C" + index + ":AO" + index].Style.Fill.PatternType = ExcelFillStyle.Solid;
            //sheet.Cells["C" + index + ":AO" + index].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Aqua);
            //sheet.Cells["C" + index + ":AO" + index].Style.Font.Bold = true;
