            //sheet.Cells["C" + index + ":AO" + index].Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            //sheet.Cells["C" + index + ":AO" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
            //sheet.Cells["C" + index + ":AO" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;


            double TotalSoLuong = 0, TotalGiaNiemYet = 0, TotalGiamGia = 0, TotalGiaBan = 0, TotalTienMat = 0, TotalTienNganHang = 0,
                    TotalNoVayNganHang = 0, TotalNoNoLe = 0, TotalCaThe = 0, TotalChiCoc = 0, TotalGiaVon = 0, TotalLoiNhuanTruocKM = 0, TotalKMQuaTangTheoXe = 0,
                    TotalKMPhiTruocBa = 0, TotalKMQuaTangKhac = 0, TotalKMPhuKien = 0, TotalKMPhuTung = 0, TotalKMDongSon = 0, TotalKMBaoHiem = 0, TotalKMHoaHong = 0, TotalKMBaoDuong = 0
                    , TotalChietKhauThuongMai = 0, TotalLoiNhuanSauChietKhau = 0, TotalLoiNhuan = 0, TotalKM_GHBH = 0;
            foreach (DataRow row in tbl.Rows)
            {
                TotalSoLuong += row["SoLuong"].ToString() == "" ? 0 : Convert.ToDouble(row["SoLuong"]);
                TotalGiaNiemYet += row["GiaNiemYet"].ToString() == "" ? 0 : Convert.ToDouble(row["GiaNiemYet"]);
