        #endregion report xe (backup)
        private void ReportDVPT()
        {
            DateTime start = DateTime.Now;
            _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportDVPT");
            _log4net.Param("ShowRoom", ShowRoom);
            var sheet = pck.Workbook.Worksheets["DT PT&DV"];
            sheet.View.FreezePanes(5, 6);
            try
            {
                var watchGetdata = new System.Diagnostics.Stopwatch();
                watchGetdata.Start();
                _log4net.Start("DB ReportDVPT");
                DataTable dtbPTDV = _tkknService.BCNgayChiTietPhieuDichVu(ConnectionString, FromDate, ToDate);
                _log4net.End("DB ReportDVPT");
                //DV
                DataView dvResultDV = dtbPTDV.DefaultView;
                dvResultDV.RowFilter = "MaLoaiPhieu = 'TDIVU' AND LoaiBaoHiem <> 'XKG' ";
                DataTable dtbDichVu = dvResultDV.ToTable();

                //DV XE CU TAN TRANG
                DataView dvResultDVTT = dtbPTDV.DefaultView;
                dvResultDVTT.RowFilter = "MaLoaiPhieu = 'TDIVU' AND LoaiBaoHiem = 'XKG' ";
                DataTable dtbDichVuTT = dvResultDVTT.ToTable();
                //Phiếu bán lẻ
                DataView dvResultBL = dtbPTDV.DefaultView;
                dvResultBL.RowFilter = "MaLoaiPhieu = 'TPHKI' AND PhanLoaiKM = 'BL' AND LoaiKM = 'BL' ";
                DataTable dtbBanLe = dvResultBL.ToTable();
                //Phiếu KM
                DataView dvResultPK = dtbPTDV.DefaultView;
                dvResultPK.RowFilter = "PhanLoaiKM = 'KM_HT_OLD' ";//bỏ
                DataTable dtbPhuKienKM = dvResultPK.ToTable();

                //Phiếu Khuyến mãi xe chưa xuất
                DataView dvResultKMChuaXuat = dtbPTDV.DefaultView;
                dvResultKMChuaXuat.RowFilter = "PhanLoaiKM = 'KM_TL' ";
