        private void ReportDoanhThuDVPT()
        {
            DateTime start = DateTime.Now;
            _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportDoanhThuDVPT");
            _log4net.Param("ShowRoom", ShowRoom);
            var sheet = pck.Workbook.Worksheets["CT TT DV&PT"];
            sheet.View.FreezePanes(6, 5);
            try
            {
                _log4net.Start("DB ReportDoanhThuDVPT");
                DataTable dtbDoanhThuDVPT = _tkknService.BCNgayDoanhThuDichVu(ConnectionString, FromDate, ToDate);
                _log4net.End("DB ReportDoanhThuDVPT");
                //PHAN DICH VU
                DataView dtvDichVu = dtbDoanhThuDVPT.DefaultView;
                dtvDichVu.RowFilter = "MaLoaiPhieu = 'TDIVU'";
                DataTable dtbDichVu = dtvDichVu.ToTable();

                //PHAN THU COC DV
                DataView dtvTCDichVu = dtbDoanhThuDVPT.DefaultView;
                dtvTCDichVu.RowFilter = "MaLoaiPhieu = 'TCODV'";
                DataTable dtbTCDichVu = dtvTCDichVu.ToTable();
                //PHAN PHU KIEN
                DataView dtvPHUKIEN = dtbDoanhThuDVPT.DefaultView;
                dtvPHUKIEN.RowFilter = "MaLoaiPhieu = 'TPHKI'";
                DataTable dtbPHUKIEN = dtvPHUKIEN.ToTable();

                #region BC Doanh Thu Dich Vụ Phụ Tùng
