        public void ReportTongChiPhi()
        {
            DateTime start = DateTime.Now;
            _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportTongChiPhi");
            _log4net.Param("ShowRoom", ShowRoom);
            var sheet = pck.Workbook.Worksheets["Tổng CP"];
            sheet.View.FreezePanes(4, 1);
            try
            {
                DataTable tbl = _tkknService.TongChiPhi(ConnectionString, FromDate, ToDate);

                #region Báo cáo tổng chi phí
                var cellA1M1 = sheet.Cells["A1:H1"];
                cellA1M1.Value = "TỔNG CHÍ PHÍ " + ShowRoom;
                cellA1M1.Merge = true;
                cellA1M1.Style.Font.Bold = true;
                cellA1M1.Style.Fill.PatternType = ExcelFillStyle.Solid;
                cellA1M1.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.BurlyWood);
                cellA1M1.Style.VerticalAlignment = ExcelVerticalAlignment.Center;
                cellA1M1.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                cellA1M1.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                cellA1M1.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                string TuNgayDenNgay_new = "Từ ngày " + 1 + "/" + ToDate.Month + "/" + ToDate.Year;
                TuNgayDenNgay_new += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                //phan fromdate và todate
                var cellA2M2 = sheet.Cells["A2:H2"];
                cellA2M2.Value = TuNgayDenNgay_new;
                cellA2M2.Merge = true;
                cellA2M2.Style.Font.Bold = true;
                cellA2M2.Style.Fill.PatternType = ExcelFillStyle.Solid;
                cellA2M2.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Aqua);
                cellA2M2.Style.VerticalAlignment = ExcelVerticalAlignment.Center;
                cellA2M2.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                cellA2M2.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                cellA2M2.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                var cellA2A3 = sheet.Cells["A3"];
                cellA2A3.Value = "STT";
                cellA2A3.Merge = true;
                cellA2A3.Style.Font.Bold = true;
                cellA2A3.Style.Fill.PatternType = ExcelFillStyle.Solid;
                cellA2A3.Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.BurlyWood);
                cellA2A3.Style.VerticalAlignment = ExcelVerticalAlignment.Center;
                cellA2A3.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
