        public void ReportXNT_XeCu()
        {

            _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportXNT_XeCu");
            _log4net.Param("ShowRoom", ShowRoom);
            DateTime start = new DateTime();
            var sheet = pck.Workbook.Worksheets["XNT-XECU"];
