                //dtbResult = _cacheManager.Get<DataTable>(CacheKey.Report.keyXNT + "dtbResult" + DateCache);
                //if (dtbResult == null)
                //{
                //    dtbResult = _tkknService.BCNgayXNT(FromDate, ToDate);
                //    _cacheManager.Set(CacheKey.Report.keyXNT + "dtbResult" + DateCache, dtbResult, CacheKey.cacheTime);
                //}
                DataTable dtbResult = _tkknService.BCNgayXNT_XECU(FromDate, ToDate);
                DataView dvCarInOut = dtbResult.DefaultView;
                dvCarInOut.RowFilter = "NhaCungCap = 'NGOAI'";
                DataTable dtbCarInOut1 = dvCarInOut.ToTable();
                string str = dtbCarInOut1.Rows.Count > 0 ? dtbCarInOut1.Rows[0]["MaModel"].ToString() : "";
                int num = dtbCarInOut1.Rows.Count;
                DataTable dtbCarInOut = dtbCarInOut1.Clone();
                _log4net.End("(" + CurrentUser.UserName + ")(" + ShowRoom + ")End DB XNT");
                _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")Start C# XNT");
                #region XeXNT
                #region Khai báo biến
                double SoLuongTonKhoDauKy = 0, TongTienTonKhoDauKy = 0
                               , SoLuongNhap = 0, TongTienNhap = 0
                               , SoLuongXuat = 0, TongTienXuat = 0
                               , SoLuongTonKhoCuoiKy = 0, TongTienTonKhoCuoiKy = 0;
