                               , SoLuongNhapXE = 0, TongTienNhapXE = 0
                               , SoLuongXuatXE = 0, TongTienXuatXE = 0
                               , SoLuongTonKhoCuoiKyXE = 0, TongTienTonKhoCuoiKyXE = 0;
                #endregion Khai báo biến

                string XuatXu = "CKD";
                int demcbu = 0;
                double sldkcbu = 0, ttdkcbu = 0, nhapdkcbu = 0, nhapttcbu = 0, slxbcbu = 0, ttxbcbu = 0, slckcbu = 0, ttckcbu = 0;
                //double sldkckd = 0, ttdkckd = 0, nhapdkckd = 0, nhapttckd = 0, slxbckd = 0, ttxbckd = 0, slckckd = 0, ttckckd = 0;
                foreach (DataRow row in (dtbCarInOut1 as DataTable).Rows)
                {
                    if (row["XuatXu"].ToString() == XuatXu)
                    {
                        sldkcbu += Convert.ToDouble(row["SoLuongTonKhoDauKy"].ToString());
                        ttdkcbu += Convert.ToDouble(row["TongTienTonKhoDauKy"].ToString());
                        nhapdkcbu += Convert.ToDouble(row["SoLuongNhap"].ToString());
                        nhapttcbu += Convert.ToDouble(row["TongTienNhap"].ToString());
                        slxbcbu += Convert.ToDouble(row["SoLuongXuat"].ToString());
                        ttxbcbu += Convert.ToDouble(row["TongTienXuat"].ToString());
                        slckcbu += Convert.ToDouble(row["SoLuongTonKhoCuoiKy"].ToString());
                        ttckcbu += Convert.ToDouble(row["TongTienTonKhoCuoiKy"].ToString());
                        demcbu++;
                    }
                    else
                    {
                        XuatXu = "CBU";
                        DataRow drCBU = dtbCarInOut1.NewRow();
                        drCBU["TenModel"] = "Tổng CKD:";
