                        drCBU["TongTienNhap"] = nhapttcbu;
                        drCBU["SoLuongXuat"] = slxbcbu;
                        drCBU["TongTienXuat"] = ttxbcbu;
                        drCBU["SoLuongTonKhoCuoiKy"] = slckcbu;
                        drCBU["TongTienTonKhoCuoiKy"] = ttckcbu;
                        dtbCarInOut1.Rows.InsertAt(drCBU, demcbu);
