                    && sheet.Cells["B" + i].Value != sheet.Cells["B" + (i - 1)].Value
                    && sheet.Cells["C" + i].Value == sheet.Cells["C" + (i - 1)].Value))
                    {
                        var Cels = sheet.Cells["C" + (dau - 1) + ":C" + (i)];
                        Cels.Value = sheet.Cells["C" + dau].Value.ToString();
                        Cels.Merge = true;
                        break;
                    }
                    else if ((i == dtbXNTTong.Rows.Count + 4
                    && sheet.Cells["B" + i].Value != sheet.Cells["B" + (i - 1)].Value
                    && sheet.Cells["C" + i].Value != sheet.Cells["C" + (i - 1)].Value)
