                            var Cels = sheet.Cells["C" + dau + ":C" + (cuoi)];
                            Cels.Value = sheet.Cells["C" + dau].Value;
                            Cels.Merge = true;
                            dau = cuoi + 1;
                            i = cuoi;
                            cuoi += dem;
                            dem = 0;
                        }
                        i++;
                    }
