                    sheet.Cells["G" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["G" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    TongTienDauKy += row["DauKy"].ToString() == "" ? 0 : Convert.ToDouble(row["DauKy"]);
                    TongTienNhapKho += row["NhapKho"].ToString() == "" ? 0 : Convert.ToDouble(row["NhapKho"]);
                    TongTienXuatKho += row["XuatKho"].ToString() == "" ? 0 : Convert.ToDouble(row["XuatKho"]);
                    TongTienCuoiKy += row["CuoiKy"].ToString() == "" ? 0 : Convert.ToDouble(row["CuoiKy"]);

                    index += 1;
