        public ActionResult ReportBCKT_TongHop(string fromDate, string toDate)
        {
            try
            {
                var pck = new ExcelPackage();
                var sheet = pck.Workbook.Worksheets.Add("BC_TongHop");
                sheet.Cells.Style.Font.Name = "Arial";
                sheet.Cells.Style.Font.Size = 10;
                sheet.Cells.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;

                #region BC_TongHop
                sheet.Row(3).Height = 30;

                var cellTitle = sheet.Cells[1, 1, 2, 7];
                cellTitle.Value = "BẢNG SO SÁNH TÀI SẢN";
                cellTitle.Merge = true;
                cellTitle.Style.Font.Bold = true;
                cellTitle.Style.Font.Size = 14;
                cellTitle.Style.VerticalAlignment = ExcelVerticalAlignment.Center;
                cellTitle.Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;

                string[] listTitle = { "DIỄN GIẢI", fromDate, toDate, "TĂNG/GIẢM " + fromDate + " -> " + toDate, "CÂN ĐỐI KQKD" };
                dynamic[] s = new dynamic[6];

                s[0] = sheet.Cells[3, 1, 3, 4];
                s[0].Value = listTitle[0].ToString();

                s[1] = sheet.Cells[3, 5, 3, 5];
                s[1].Value = listTitle[1].ToString();

                s[2] = sheet.Cells[3, 6, 3, 6];
                s[2].Value = listTitle[2].ToString();

                s[3] = sheet.Cells[3, 7, 3, 7];
                s[3].Value = listTitle[3].ToString();

                s[4] = sheet.Cells[3, 9, 3, 11];
                s[4].Value = listTitle[4].ToString();

                for (int k = 0; k < listTitle.Length; k++)
                {
                    s[k].Merge = true;
                    s[k].Style.Font.Bold = true;
                    s[k].Style.Fill.PatternType = ExcelFillStyle.Solid;
                    s[k].Style.WrapText = true;
                    s[k].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml("#c496ff"));
                    s[k].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml("#000000"));
                    s[k].Style.VerticalAlignment = ExcelVerticalAlignment.Center;
                    s[k].Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                    s[k].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    s[k].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                    s[k].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    s[k].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                }

                // lấy dữ liệu

                DataTable dtb = _tkknService.ReportTongHop(ConnectionString, Convert.ToDateTime(fromDate), Convert.ToDateTime(toDate));
                int i = 1;
                int x = 1, y = 1;
                string Nhom = ""; double TongDauKy = 0, TongCuoiKy = 0;
                Nhom = dtb.Rows[0]["Nhom"].ToString();
                TongDauKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[0]["DauKy"].ToString()) ? "0" : (dtb.Rows[0]["DauKy"].ToString()));
                TongCuoiKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[0]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[0]["CuoiKy"].ToString()));
                while (i < dtb.Rows.Count)
                {

                    if (Nhom == dtb.Rows[i]["Nhom"].ToString())
                    {
                        TongDauKy += double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["DauKy"].ToString()) ? "0" : (dtb.Rows[i]["DauKy"].ToString()));
                        TongCuoiKy += double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[i]["CuoiKy"].ToString()));
                        i++;
                    }
                    else
                    {
                        DataRow dr;
                        dr = dtb.NewRow();
                        dr["Nhom"] = Nhom;
                        dr["ID"] = "Tổng Cộng";
                        dr["DauKy"] = TongDauKy.ToString();
                        dr["CuoiKy"] = TongCuoiKy.ToString();
                        Nhom = dtb.Rows[i]["Nhom"].ToString();
                        TongDauKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["DauKy"].ToString()) ? "0" : (dtb.Rows[i]["DauKy"].ToString()));
                        TongCuoiKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[i]["CuoiKy"].ToString()));
                        dtb.Rows.InsertAt(dr, i);
                        i = i + 2;
                    }
                }

                DataRow dr1;
                dr1 = dtb.NewRow();
                dr1["Nhom"] = Nhom;
                dr1["ID"] = "Tổng Cộng";
                dr1["DauKy"] = TongDauKy.ToString();
                dr1["CuoiKy"] = TongCuoiKy.ToString();
                dtb.Rows.Add(dr1);

                sheet.Cells.AutoFitColumns();
                String AsBase64String = Convert.ToBase64String(pck.GetAsByteArray());
                return Json(new
                {
                    IsError = false,
                    Obj = AsBase64String,
                    Message = "Xuất excel thành công"
                });

                #endregion
            }
            catch (Exception ex)
            {
                return null;
            }
        }




        public string ReportBCKT_KQKD(DateTime fromDate, DateTime toDate)
        {
            try
            {
                byte[] result = null;
                // lấy dữ liệu phiếu công vợ DV BH             
                DataTable dtb = _tkknService.ReportKQKD(ConnectionString, FromDate, ToDate);

                DataView dtvCKD = dtb.DefaultView;
                dtvCKD.RowFilter = "XuatXu = 'CKD'";
                DataTable dtbCKD = dtvCKD.ToTable();

                DataView dtvCBU = dtb.DefaultView;
                dtvCBU.RowFilter = "XuatXu = 'CBU'";
                DataTable dtbCBU = dtvCBU.ToTable();

                DataView dtvLe = dtb.DefaultView;
                dtvLe.RowFilter = "VayNH = '0'";
                DataTable dtbLe = dtvLe.ToTable();

                DataView dtvGop = dtb.DefaultView;
                dtvGop.RowFilter = "VayNH > '0'";
                DataTable dtbGop = dtvGop.ToTable();

                string From = FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
                string To = ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                //phan le va gop



                ViewBag.From = From;
                ViewBag.To = To;
                ViewBag.dtbCKD = dtbCKD;
                ViewBag.dtbCBU = dtbCBU;
                ViewBag.dtbLe = dtbLe;
                ViewBag.dtbGop = dtbGop;

                return "";
            }
            catch (Exception ex)
            {
                log.Error($"ReportBCKT_HDD_{fromDate.ToString("dd/MM/yyyy")}_{toDate.ToString("dd/MM/yyyy")}: " + ex.Message.ToString());
                return "";
            }
        }

