        public ActionResult Report_BC_KiemToan(DateTime fromDate, DateTime toDate, string reportType, string type)
        {
            //fromDate = Convert.ToDateTime("2023/08/27");
            //toDate = Convert.ToDateTime("2023/08/31");
            byte[] result = null;
            try
            {
                FileInfo template = new FileInfo(@"" + System.AppDomain.CurrentDomain.BaseDirectory + "Views\\FileMau\\TemplateExcelBCKT.xlsx");
                using (ExcelPackage pck = new ExcelPackage(template, true))
                {
                    switch (reportType)
                    {
                        case "BCKT_TatCa":
                            goto BCKT_TatCa;
                        case "BCKT_CanDoi":
                            goto BCKT_CanDoi;
                        case "BCKT_TongHop":
                            goto BCKT_TongHop;
                        case "BCKT_ChiTiet":
                            goto BCKT_ChiTiet;
                        case "BCKT_TamUng":
                            goto BCKT_TamUng;
                        case "BCKT_CongNoDV_BH":
                            goto BCKT_CongNoDV_BH;
                        case "BCKT_XNT":
                            goto BCKT_XNT;
                    }

                BCKT_TatCa:
                #region BCKT_TatCa
                #endregion
                BCKT_CanDoi:
                    #region BCKT_CanDoi:
                    // lấy dữ liệu báo cáo cân đối
                    DataTable dtCanDoi = _tkknService.ReportBCKTCanDoi(ConnectionString, fromDate, toDate);
                    if (dtCanDoi != null && dtCanDoi.Rows.Count > 0)
                    {

                    }

                #endregion
                BCKT_TongHop:
                    #region BCKT_TongHop:
                    // lấy dữ liệu báo cáo tổng hợp
                    DataTable dtTongHop = _tkknService.ReportTongHop(ConnectionString, fromDate, toDate);
                #endregion
                BCKT_ChiTiet:
                    #region BCKT_ChiTiet

                    //   lấy dữ liệu phiếu chi tiết


                    DataTable dtChiTiet = _tkknService.ReportChiTiet(ConnectionString, fromDate, toDate);

                    if (dtChiTiet != null && dtChiTiet.Rows.Count > 0)
                    {
                        var sheetChiTiet = pck.Workbook.Worksheets["ChiTiet"];
                        // title
                        sheetChiTiet.Cells["E3"].Value = fromDate.AddDays(-1).ToString("dd/MM/yyyy");
                        sheetChiTiet.Cells["F3"].Value = toDate.ToString("dd/MM/yyyy");
                        sheetChiTiet.Cells["G3"].Value = $"TĂNG/GIẢM {fromDate.ToString("dd")} -> {toDate.ToString("dd/MM/yyyy")}";
                        sheetChiTiet.Cells["G3"].Style.WrapText = true;

                        string Nhom = dtChiTiet.Rows[0]["Nhom"].ToString().TrimStart().TrimEnd();
                        string ID = dtChiTiet.Rows[0]["ID"].ToString().TrimStart().TrimEnd();
                        string ChiTiet = dtChiTiet.Rows[0]["ChiTiet"].ToString().TrimStart().TrimEnd();
                        int rowChiTiet = 4, rowBeginNhom = 4, rowBeginID = 4, rowBeginChiTiet = 4;

                        string NhomNext = "", IDNext = "", ChiTietNext = "", DienGiai = "";
                        for (int i = 0; i <= dtChiTiet.Rows.Count; i++)
                        {
                            // dòng dữ liệu cuối cùng
                            if (i == dtChiTiet.Rows.Count)
                            {
                                NhomNext = "";
                                goto ENDROW;
                            }
                            else
                                NhomNext = dtChiTiet.Rows[i]["Nhom"].ToString().TrimStart().TrimEnd();

                            // lấy dữ liệu 
                            IDNext = dtChiTiet.Rows[i]["ID"].ToString().TrimStart().TrimEnd();
                            ChiTietNext = dtChiTiet.Rows[i]["ChiTiet"].ToString().TrimStart().TrimEnd();
                            DienGiai = dtChiTiet.Rows[i]["DienGiai"].ToString().TrimStart().TrimEnd();
                            var DauKy = dtChiTiet.Rows[i]["DauKy"].ToString().TrimStart().TrimEnd();
                            var CuoiKy = dtChiTiet.Rows[i]["CuoiKy"].ToString().TrimStart().TrimEnd();

                            sheetChiTiet.Cells[rowChiTiet, 1].Value = NhomNext;
                            sheetChiTiet.Cells[rowChiTiet, 2].Value = IDNext;
                            sheetChiTiet.Cells[rowChiTiet, 3].Value = ChiTietNext;
                            sheetChiTiet.Cells[rowChiTiet, 4].Value = DienGiai;
                            sheetChiTiet.Cells[rowChiTiet, 5].Value = string.IsNullOrEmpty(DauKy) ? 0 : double.Parse(DauKy);
                            sheetChiTiet.Cells[rowChiTiet, 6].Value = string.IsNullOrEmpty(CuoiKy) ? 0 : double.Parse(CuoiKy);
                            sheetChiTiet.Cells[rowChiTiet, 7].Formula = $"=F{rowChiTiet} - E{rowChiTiet}";

                        ENDROW:
                            // gom thành 1 dòng nếu ID = ''
                            if (string.IsNullOrEmpty(IDNext) && string.IsNullOrEmpty(ChiTietNext) && string.IsNullOrEmpty(DienGiai))
                            {
                                sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Merge = true;
                                sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Font.Bold = true;
                                sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Fill.PatternType = ExcelFillStyle.Solid;
                                sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml("#ffa500"));
                                sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml("#202021"));
                                rowBeginNhom = rowChiTiet + 1;
                                rowBeginID = rowChiTiet + 1;
                                rowBeginChiTiet = rowChiTiet + 1;
                                rowChiTiet = rowChiTiet + 1;
                                Nhom = NhomNext;
                                ID = IDNext;
                                ChiTiet = ChiTietNext;
                                continue;
                            }


                            // kiểm tra dòng dữ liệu hiện tại với dòng dữ liệu trước đó
                            if (NhomNext != Nhom) // khác nhóm hoặc dòng tổng cộng nhóm hoặc dòng tổng cộng id
                            {
                                if (NhomNext == IDNext) // dòng tổng cộng của nhóm
                                {
                                    // dòng tổng cộng
                                    sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 4].Merge = true;
                                    sheetChiTiet.Row(rowChiTiet).Height = 20;
                                    sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Font.Bold = true;
                                    sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Fill.PatternType = ExcelFillStyle.Solid;
                                    sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml("#99f7af"));
                                    sheetChiTiet.Cells[rowChiTiet, 1, rowChiTiet, 7].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml("#080cff"));

                                    // gom nhóm 
                                    if (rowBeginNhom == rowChiTiet)
                                        rowChiTiet++;

                                    sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Merge = true;
                                    sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Font.Bold = true;
                                    sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Fill.PatternType = ExcelFillStyle.Solid;
                                    sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml("#74a4fc"));
                                    sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml("#202021"));

                                    // cập nhật lại nhóm mới
                                    rowBeginNhom = rowChiTiet + 1;
                                }
                                else // khác tổng cộng nhóm
                                {
                                    if (dtChiTiet.Rows[i - 1]["Nhom"].ToString().TrimStart().TrimEnd() != dtChiTiet.Rows[i - 1]["ID"].ToString().TrimStart().TrimEnd())
                                    {
                                        // gom nhóm 
                                        if (rowBeginNhom == rowChiTiet)
                                            rowChiTiet++;

                                        sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Merge = true;
                                        sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Font.Bold = true;
                                        sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Fill.PatternType = ExcelFillStyle.Solid;
                                        sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml("#74a4fc"));
                                        sheetChiTiet.Cells[rowBeginNhom, 1, rowChiTiet - 1, 1].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml("#202021"));
                                    }
                                    rowBeginNhom = rowChiTiet;
                                }
                                Nhom = NhomNext;
                            }
                            if (IDNext != ID) // gom ID 
                            {
                                if (NhomNext == IDNext) // dòng tổng cộng của nhóm
                                {
                                    if (rowBeginID == rowChiTiet)
                                        rowChiTiet++;
                                    // gom nhóm 
                                    sheetChiTiet.Cells[rowBeginID, 2, rowChiTiet - 1, 2].Merge = true;
                                    rowBeginID = rowChiTiet + 1;
                                }
                                else
                                {
                                    if (dtChiTiet.Rows[i - 1]["Nhom"].ToString().TrimStart().TrimEnd() != dtChiTiet.Rows[i - 1]["ID"].ToString().TrimStart().TrimEnd())
                                    {
                                        if (rowBeginID == rowChiTiet)
                                            rowChiTiet++;

                                        sheetChiTiet.Cells[rowBeginID, 2, rowChiTiet - 1, 2].Merge = true;

                                        if (IDNext == ChiTietNext && ChiTietNext == DienGiai)
                                        {
                                            sheetChiTiet.Cells[rowChiTiet, 2, rowChiTiet, 4].Value = "";
                                            sheetChiTiet.Cells[rowChiTiet, 2, rowChiTiet, 7].Style.Font.Bold = true;
                                            sheetChiTiet.Cells[rowChiTiet, 2, rowChiTiet, 7].Style.Fill.PatternType = ExcelFillStyle.Solid;
                                            sheetChiTiet.Cells[rowChiTiet, 2, rowChiTiet, 7].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml("#8af1ff"));
                                            sheetChiTiet.Cells[rowChiTiet, 2, rowChiTiet, 7].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml("#202021"));
                                        }
                                    }
                                    rowBeginID = rowChiTiet;
                                }
                                ID = IDNext;
                            }
                            // gom chi tiết
                            if (ChiTietNext != ChiTiet)
                            {
                                if (NhomNext == IDNext) // dòng tổng cộng của nhóm
                                {
                                    if (rowBeginChiTiet == rowChiTiet)
                                        rowChiTiet++;
                                    // gom nhóm 
                                    sheetChiTiet.Cells[rowBeginChiTiet, 3, rowChiTiet - 1, 3].Merge = true;
                                    rowBeginID = rowChiTiet + 1;
                                }
                                else
                                {

                                    if (dtChiTiet.Rows[i - 1]["Nhom"].ToString().TrimStart().TrimEnd() != dtChiTiet.Rows[i - 1]["ID"].ToString().TrimStart().TrimEnd())
                                    {
                                        if (rowBeginChiTiet == rowChiTiet)
                                            rowChiTiet++;
                                        sheetChiTiet.Cells[rowBeginChiTiet, 3, rowChiTiet - 1, 3].Merge = true;
                                    }

                                    rowBeginChiTiet = rowChiTiet;
                                }
                                ChiTiet = ChiTietNext;
                            }
                            rowChiTiet++;
                        }
                        --rowChiTiet;
                        sheetChiTiet.Cells[$"A4:G{rowChiTiet - 1}"].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                        sheetChiTiet.Cells[$"A4:G{rowChiTiet - 1}"].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                        sheetChiTiet.Cells[$"A4:G{rowChiTiet - 1}"].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                        sheetChiTiet.Cells[$"A4:G{rowChiTiet - 1}"].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    }

