                            sheetXNT.Cells[indexModel, 12].Value = int.Parse(dtbXNT.Rows[i]["SoLuongXuat"].ToString());
                            sheetXNT.Cells[indexModel, 13].Value = double.Parse(dtbXNT.Rows[i]["TongTienXuat"].ToString());
                            sheetXNT.Cells[indexModel, 14].Value = int.Parse(dtbXNT.Rows[i]["SoLuongTonKhoCuoiKy"].ToString());
