                        sheetXNT.Cells[$"B6:O{indexModel}"].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                        sheetXNT.Cells[$"B6:O{indexModel}"].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                        sheetXNT.Cells[$"B6:O{indexModel}"].Style.Border.Top.Style = ExcelBorderStyle.Thin;

                        var dtbXNTn = (from row in dtXNT.AsEnumerable() where row.Field<string>("NhaCungCap") == "NGOAI" select row).CopyToDataTable();

                        int rowXeNgoai = indexModel + 2;
