                        xeNgoai.Value = "XE NGOÀI";
                        xeNgoai.Merge = true;
                        xeNgoai.Style.Font.Bold = true;
                        rowXeNgoai++;
                        for (int i = 0; i < dtbXNTn.Rows.Count; i++)
                        {
