                            sheetXNT.Cells[rowXeNgoai, 3].Value = dtbXNTn.Rows[i]["MaModel"].ToString();
                            sheetXNT.Cells[rowXeNgoai, 4].Value = dtbXNTn.Rows[i]["TenMau"].ToString();
                            sheetXNT.Cells[rowXeNgoai, 5].Value = double.Parse(dtbXNTn.Rows[i]["GiaVon"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 6].Value = int.Parse(dtbXNTn.Rows[i]["SoLuongTonKhoDauKy"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 7].Value = double.Parse(dtbXNTn.Rows[i]["TongTienTonKhoDauKy"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 8].Value = int.Parse(dtbXNTn.Rows[i]["SoLuongNhap"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 9].Value = double.Parse(dtbXNTn.Rows[i]["TongTienNhap"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 12].Value = int.Parse(dtbXNTn.Rows[i]["SoLuongXuat"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 13].Value = double.Parse(dtbXNTn.Rows[i]["TongTienXuat"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 14].Value = int.Parse(dtbXNTn.Rows[i]["SoLuongTonKhoCuoiKy"].ToString());
                            sheetXNT.Cells[rowXeNgoai, 15].Value = double.Parse(dtbXNTn.Rows[i]["TongTienTonKhoCuoiKy"].ToString());
                            rowXeNgoai++;
                        }

                        // tổng cộng xe ngoài

                        dynamic[] xn = new dynamic[256];
                        sheetXNT.Row(rowXeNgoai).Height = 25;
                        foreach (char c in titleA)
                        {
                            int index = (int)c;
                            if (c == 'E')
                            {
                                xn[index] = sheetXNT.Cells[$"B{rowXeNgoai}:E{rowXeNgoai}"];
                                xn[index].Value = "TỔNG CỘNG";
                                xn[index].Merge = true;
                            }
                            else
                            {
                                xn[index] = sheetXNT.Cells[c.ToString() + rowXeNgoai.ToString()];
                                xn[index].Formula = $"=SUM({c}6:{c}{rowXeNgoai - 1})";
                            }

                            xn[index].Style.Font.Bold = true;
                            xn[index].Style.Fill.PatternType = ExcelFillStyle.Solid;
                            xn[index].Style.Fill.BackgroundColor.SetColor(System.Drawing.ColorTranslator.FromHtml("#f5e042"));
                            xn[index].Style.Font.Color.SetColor(System.Drawing.ColorTranslator.FromHtml("#f71b1b"));
                        }

                        sheetXNT.Cells[$"B{indexModel + 2}:O{rowXeNgoai}"].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                        sheetXNT.Cells[$"B{indexModel + 2}:O{rowXeNgoai}"].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                        sheetXNT.Cells[$"B{indexModel + 2}:O{rowXeNgoai}"].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                        sheetXNT.Cells[$"B{indexModel + 2}:O{rowXeNgoai}"].Style.Border.Top.Style = ExcelBorderStyle.Thin;

                        if (reportType != "BCKT_TatCa")
                            goto EXPORT;
                    }

                #endregion
                EXPORT:
                    result = pck.GetAsByteArray();
                }

                string result64 = Convert.ToBase64String(result);
                if (!string.IsNullOrEmpty(result64))
                {
                    return Json(new
                    {
                        IsError = false,
                        Obj = result64,
                        Message = "Xuất excel thành công"
                    });
                }
                else
                {
                    return Json(new
                    {
                        IsError = true,
                        Message = "Không có dữ liệu báo cáo"
                    });
                }
            }
            catch (Exception ex)
            {
                log.Error($"Report_BC_KiemToan_{fromDate.ToString("dd/MM/yyyy")}_{toDate.ToString("dd/MM/yyyy")}_{reportType}: " + ex.Message.ToString());
                return Json(new { IsError = true, Message = ex.Message.ToString() });
            }
        }
        public ActionResult Report_BC_KTNB(DateTime fromDate, DateTime toDate, string reportType, string type)
        {
            byte[] result = null;
            try
            {
                FileInfo template = new FileInfo(@"" + System.AppDomain.CurrentDomain.BaseDirectory + "Views\\FileMau\\Template_BaoCaoKTNB.xlsx");
                using (ExcelPackage pck = new ExcelPackage(template, true))
                {
                    #region TONG TAI SAN

                    DataTable tongTS_tbl = _tkknService.BCNgay_KTNB_TongTaiSan(ConnectionString, fromDate, toDate);
                    var sheet_TONG_TAISAN = pck.Workbook.Worksheets["TỔNG TÀI SẢN"];
                    var cellA2N2 = sheet_TONG_TAISAN.Cells["A2"];
                    cellA2N2.Value = "Từ ngày " + fromDate.ToString("dd/MM/yyyy") + " đến ngày " + toDate.ToString("dd/MM/yyyy");
                    var dtb = tongTS_tbl.AsEnumerable()
                     .Select(row => new
                     {
                         HangMuc = row.Field<string>("HangMuc"),
                         DauKy = row["DauKy"] != DBNull.Value ? Convert.ToDecimal(row["DauKy"]) : 0,
                         PhatSinhTang = row["PhatSinhTang"] != DBNull.Value ? Convert.ToDecimal(row["PhatSinhTang"]) : 0,
                         PhatSinhGiam = row["PhatSinhGiam"] != DBNull.Value ? Convert.ToDecimal(row["PhatSinhGiam"]) : 0,
                         SoCuoiKyTien = row["CuoiKy"] != DBNull.Value ? Convert.ToDecimal(row["CuoiKy"]) : 0,
                         GhiChu = row["GhiChu"] != DBNull.Value ? row["GhiChu"].ToString():""
                     }).ToList();

                    int index = 4;
                    sheet_TONG_TAISAN.Cells[index, 1, dtb.Count(), 6].LoadFromCollection(dtb);

                    for (int i = 0; i < tongTS_tbl.Rows.Count; i++)
                    {
                        int rowIndex = index + i;
                        //backgroud color
                        string bgcolor = tongTS_tbl.Rows[i]["bgcolor"].ToString().Trim();
                        if (!string.IsNullOrWhiteSpace(bgcolor))
                        {
                            sheet_TONG_TAISAN.Cells[rowIndex, 1, rowIndex, 6].Style.Fill.PatternType = ExcelFillStyle.Solid;
                            //Color backgroundColor = Color.FromName(bgcolor);
                            sheet_TONG_TAISAN.Cells[rowIndex, 1, rowIndex, 6].Style.Fill.BackgroundColor.SetColor(ColorTranslator.FromHtml(bgcolor));
                        }
                        //color
                        string color = tongTS_tbl.Rows[i]["color"].ToString().Trim();
                        if (!string.IsNullOrWhiteSpace(color))
                        {
                            // Color colorfont = Color.FromName(color);
                            sheet_TONG_TAISAN.Cells[rowIndex, 1, rowIndex, 6].Style.Font.Color.SetColor(ColorTranslator.FromHtml(color));
                        }
                        //fontWeight
                        string fontWeight = tongTS_tbl.Rows[i]["fontWeight"].ToString().Trim();
                        bool isBold = fontWeight == "bold";
                        var range = sheet_TONG_TAISAN.Cells[rowIndex, 1, rowIndex, 6];
                        range.Style.Font.Bold = isBold;
                    }
                    sheet_TONG_TAISAN.Cells[index, 1, dtb.Count() + 3, 6].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet_TONG_TAISAN.Cells[index, 1, dtb.Count() + 3, 6].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet_TONG_TAISAN.Cells[index, 1, dtb.Count() + 3, 6].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    sheet_TONG_TAISAN.Cells[index, 1, dtb.Count() + 3, 6].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                    sheet_TONG_TAISAN.Cells[index, 2, dtb.Count() + 3, 6].Style.Numberformat.Format = "0,##";
                    #endregion
                    result = pck.GetAsByteArray();
                }

                string result64 = Convert.ToBase64String(result);
                if (!string.IsNullOrEmpty(result64))
                {
                    return Json(new
                    {
                        IsError = false,
                        Obj = result64,
                        Message = "Xuất excel thành công"
                    });
                }
                else
                {
                    return Json(new
                    {
                        IsError = true,
                        Message = "Không có dữ liệu báo cáo"
                    });
                }
            }
            catch (Exception ex)
            {
                log.Error($"Report_BC_KiemToan_{fromDate.ToString("dd/MM/yyyy")}_{toDate.ToString("dd/MM/yyyy")}_{reportType}: " + ex.Message.ToString());
                return Json(new { IsError = true, Message = ex.Message.ToString() });
            }

        }

        public ActionResult ReportAll_KiemToan(DateTime FromDate, DateTime ToDate)
        {
            try
            {
                this.FromDate = FromDate;
                this.ToDate = ToDate;
                TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
                TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                DenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                string str = Server.MapPath("~\\Views\\FileMau\\Template_KiemToan.xlsx");
                FileInfo template = new FileInfo(str);

                pck = new ExcelPackage(template, true);

                //pck = new ExcelPackage();

                //lstSheetsName.AddRange(new string[]
                //            {
                //            "TongHop"
                //            });



                foreach (string s in lstSheetsName)
                {
                    pck.Workbook.Worksheets.Add(s);
                    pck.Workbook.Worksheets[s].Cells.Style.Font.Name = "Arial";
                }

                string strFileName = "Bao cao thu chi " + ShowRoom + FromDate.ToString("dd.MM.yyyy") + "_" + ToDate.ToString("dd.MM.yyyy") + "-" + DateTime.Now.ToString("hhMMssfff") + ".xlsx";
                ReportTongHop();
                ReportChiTiet();
                ReportKQKD();
                return new ExcelInsuranceDownload(pck, strFileName);
            }
            catch (Exception ex)
            {
                _log4net.Error(ex);
            }
            return View();
        }

