        public ActionResult BCKiemToan_BCThang(DateTime FromDate, DateTime ToDate)
        {
            DataTable dt = _tkknService.ReportBCKiemToan_Thang(ConnectionString, FromDate, ToDate);
            string From = FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            string To = ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            //int cot = 0;
            //cot = dt.Columns.Count - 70;
            ViewBag.From = From;
            ViewBag.To = To;
            ViewBag.dt = dt;
            //ViewBag.cot = cot;
            return PartialView();
        }

        public void ReportTongHop()
        {
            try
            {
                var sheet = pck.Workbook.Worksheets["TongHop"];
                sheet.View.FreezePanes(3, 1);
                DataTable dtb = _tkknService.ReportTongHop(ConnectionString, FromDate, ToDate);
                int i = 1;
                #region BẢNG SO SÁNH TÀI SẢN
                string Nhom = ""; double TongDauKy = 0, TongCuoiKy = 0;
                Nhom = dtb.Rows[0]["Nhom"].ToString();
                TongDauKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[0]["DauKy"].ToString()) ? "0" : (dtb.Rows[0]["DauKy"].ToString()));
                TongCuoiKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[0]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[0]["CuoiKy"].ToString()));
                while (i < dtb.Rows.Count)
                {

                    if (Nhom == dtb.Rows[i]["Nhom"].ToString())
                    {
                        TongDauKy += double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["DauKy"].ToString()) ? "0" : (dtb.Rows[i]["DauKy"].ToString()));
                        TongCuoiKy += double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[i]["CuoiKy"].ToString()));
                        i++;
                    }
                    else
                    {
                        DataRow dr;
                        dr = dtb.NewRow();
                        dr["Nhom"] = Nhom;
                        dr["ID"] = "Tổng Cộng";
                        dr["DauKy"] = TongDauKy.ToString();
                        dr["CuoiKy"] = TongCuoiKy.ToString();
                        Nhom = dtb.Rows[i]["Nhom"].ToString();
                        TongDauKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["DauKy"].ToString()) ? "0" : (dtb.Rows[i]["DauKy"].ToString()));
                        TongCuoiKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[i]["CuoiKy"].ToString()));
                        dtb.Rows.InsertAt(dr, i);
                        i = i + 2;
                    }
                }
                DataRow dr1;
                dr1 = dtb.NewRow();
                dr1["Nhom"] = Nhom;
                dr1["ID"] = "Tổng Cộng";
                dr1["DauKy"] = TongDauKy.ToString();
                dr1["CuoiKy"] = TongCuoiKy.ToString();
                dtb.Rows.Add(dr1);

                var cellE2 = sheet.Cells["E2"];
                cellE2.Value = FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
                cellE2.Style.Font.Bold = true;

                var cellF2 = sheet.Cells["F2"];
                cellF2.Value = ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                cellF2.Style.Font.Bold = true;
                int index = 3;
                double TangGiam = 0, TongTangGiam = 0, TongDauKyTotal = 0, TongCuoiKyTotal = 0;
                foreach (DataRow row in dtb.Rows)
                {
                    TongDauKyTotal += double.Parse(string.IsNullOrEmpty(row["DauKy"].ToString()) ? "0" : (row["DauKy"].ToString()));
                    TongCuoiKyTotal += double.Parse(string.IsNullOrEmpty(row["CuoiKy"].ToString()) ? "0" : (row["CuoiKy"].ToString()));
                    TangGiam = double.Parse(string.IsNullOrEmpty(row["CuoiKy"].ToString()) ? "0" : (row["CuoiKy"].ToString())) - double.Parse(string.IsNullOrEmpty(row["DauKy"].ToString()) ? "0" : (row["DauKy"].ToString()));
                    TongTangGiam += TangGiam;

                    sheet.Cells["A" + index].Value = row["Nhom"].ToString();
                    sheet.Cells["A" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["B" + index + ":D" + index].Value = row["ID"].ToString();
                    sheet.Cells["B" + index + ":D" + index].Merge = true;
                    sheet.Cells["B" + index + ":D" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["B" + index + ":D" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["E" + index].Value = Convert.ToDouble(row["DauKy"].ToString());
                    sheet.Cells["E" + index].Style.Numberformat.Format = format;
                    sheet.Cells["E" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["E" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;


                    sheet.Cells["E" + index].Value = Convert.ToDouble(row["DauKy"].ToString());
                    sheet.Cells["E" + index].Style.Numberformat.Format = format;
                    sheet.Cells["E" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["E" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["F" + index].Value = Convert.ToDouble(row["CuoiKy"].ToString());
                    sheet.Cells["F" + index].Style.Numberformat.Format = format;
                    sheet.Cells["F" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["F" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["G" + index].Value = TangGiam;
                    sheet.Cells["G" + index].Style.Numberformat.Format = format;
                    sheet.Cells["G" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["G" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                    index += 1;
                }
                int j = 3;
                int cuoi2 = 3, dau = 3, dem = 0;
                while (j <= dtb.Rows.Count + 2)
                {
                    if (j == dtb.Rows.Count + 2 && sheet.Cells["A" + j].Value.ToString() == sheet.Cells["A" + (j - 1)].Value.ToString())
                    {
                        var Cels = sheet.Cells["A" + dau + ":A" + (j)];
                        Cels.Value = sheet.Cells["A" + dau].Value.ToString();
                        Cels.Merge = true;
                        break;
                    }
                    else if (j == dtb.Rows.Count + 2)
                    {
                        var Celss = sheet.Cells["A" + j + ":A" + j];
                        Celss.Value = sheet.Cells["A" + dau].Value.ToString();
                        Celss.Merge = true;
                        break;
                    }
                    else
                    {
                        if (sheet.Cells["A" + j].Value.ToString() == sheet.Cells["A" + (j + 1)].Value.ToString())
                        {
                            cuoi2 = j + 1;
                        }
                        else
                        {
                            dem++;
                            var Celss = sheet.Cells["A" + dau + ":A" + (cuoi2)];
                            Celss.Value = sheet.Cells["A" + dau].Value.ToString();
                            Celss.Merge = true;
                            dau = cuoi2 + 1;
                            j = cuoi2;
                            cuoi2 += dem;
                            dem = 0;
                        }
                        j++;
                    }
                }
                sheet.Cells["A" + index + ":D" + index].Value = "TỔNG CỘNG";
                sheet.Cells["A" + index + ":D" + index].Style.Font.Bold = true;
                sheet.Cells["A" + index + ":D" + index].Merge = true;
                sheet.Cells["A" + index + ":D" + index].Style.Fill.PatternType = ExcelFillStyle.Solid;
                sheet.Cells["A" + index + ":D" + index].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
                sheet.Cells["A" + index + ":D" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A" + index + ":D" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                sheet.Cells["E" + index].Value = TongDauKyTotal;
                sheet.Cells["E" + index].Style.Numberformat.Format = format;
                sheet.Cells["E" + index].Style.Font.Bold = true;
                sheet.Cells["E" + index].Style.Fill.PatternType = ExcelFillStyle.Solid;
                sheet.Cells["E" + index].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
                sheet.Cells["E" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["E" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                sheet.Cells["F" + index].Value = TongCuoiKyTotal;
                sheet.Cells["F" + index].Style.Numberformat.Format = format;
                sheet.Cells["F" + index].Style.Font.Bold = true;
                sheet.Cells["F" + index].Style.Fill.PatternType = ExcelFillStyle.Solid;
                sheet.Cells["F" + index].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
                sheet.Cells["F" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["F" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                sheet.Cells["G" + index].Value = TongTangGiam;
                sheet.Cells["G" + index].Style.Numberformat.Format = format;
                sheet.Cells["G" + index].Style.Font.Bold = true;
                sheet.Cells["G" + index].Style.Fill.PatternType = ExcelFillStyle.Solid;
                sheet.Cells["G" + index].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
                sheet.Cells["G" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["G" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                #endregion

                #region CÂN ĐỐI KQKD
                int indexKQKD = 2;
                int x = 0, y = 0;
                DataTable dtCanDoiKQKD = _tkknService.ReportCanDoiKQKD(ConnectionString, FromDate, ToDate);
                string NhomKQKDTang = "", NhomKQKDGiam = ""; double TongCongKQKDTang = 0, TongCongKQKDGiam = 0;
                DataTable CanDoiKQKDTang = new DataTable();
                CanDoiKQKDTang.Columns.Add("Nhom", typeof(string));
                CanDoiKQKDTang.Columns.Add("HangMuc", typeof(string));
                CanDoiKQKDTang.Columns.Add("SoTien", typeof(double));
                CanDoiKQKDTang.Columns.Add("TangGiam", typeof(int));
                DataTable CanDoiKQKDGiam = new DataTable();
                CanDoiKQKDGiam.Columns.Add("Nhom", typeof(string));
                CanDoiKQKDGiam.Columns.Add("HangMuc", typeof(string));
                CanDoiKQKDGiam.Columns.Add("SoTien", typeof(double));
                CanDoiKQKDGiam.Columns.Add("TangGiam", typeof(int));
                double TONGCONG = 0;
                for (int z = 0; z < dtCanDoiKQKD.Rows.Count; z++)
                {
                    TONGCONG += Convert.ToDouble(dtCanDoiKQKD.Rows[z]["SoTien"]);
                    if (Convert.ToDouble(dtCanDoiKQKD.Rows[z]["TangGiam"]) == 1)
                    {
                        DataRow dr = CanDoiKQKDTang.NewRow();
                        dr["Nhom"] = dtCanDoiKQKD.Rows[z]["Nhom"];
                        dr["HangMuc"] = dtCanDoiKQKD.Rows[z]["HangMuc"];
                        dr["SoTien"] = dtCanDoiKQKD.Rows[z]["SoTien"];
                        dr["TangGiam"] = dtCanDoiKQKD.Rows[z]["TangGiam"];
                        CanDoiKQKDTang.Rows.Add(dr);
                    }
                    else if (Convert.ToDouble(dtCanDoiKQKD.Rows[z]["TangGiam"]) == -1)
                    {
                        DataRow dr = CanDoiKQKDGiam.NewRow();
                        dr["Nhom"] = dtCanDoiKQKD.Rows[z]["Nhom"];
                        dr["HangMuc"] = dtCanDoiKQKD.Rows[z]["HangMuc"];
                        dr["SoTien"] = dtCanDoiKQKD.Rows[z]["SoTien"];
                        dr["TangGiam"] = dtCanDoiKQKD.Rows[z]["TangGiam"];
                        CanDoiKQKDGiam.Rows.Add(dr);
                    }
                }
                if (CanDoiKQKDTang.Rows.Count > 0)
                {
                    NhomKQKDTang = CanDoiKQKDTang.Rows[0]["Nhom"].ToString();
                    TongCongKQKDTang = double.Parse(string.IsNullOrEmpty(CanDoiKQKDTang.Rows[0]["SoTien"].ToString()) ? "0" : (CanDoiKQKDTang.Rows[0]["SoTien"].ToString()));
                }
                if (CanDoiKQKDGiam.Rows.Count > 0)
                {
                    NhomKQKDGiam = CanDoiKQKDGiam.Rows[0]["Nhom"].ToString();
                    TongCongKQKDGiam = double.Parse(string.IsNullOrEmpty(CanDoiKQKDGiam.Rows[0]["SoTien"].ToString()) ? "0" : (CanDoiKQKDGiam.Rows[0]["SoTien"].ToString()));
                }
                while (x < CanDoiKQKDTang.Rows.Count)
                {
                    if (NhomKQKDTang == CanDoiKQKDTang.Rows[x]["Nhom"].ToString())
                    {
                        TongCongKQKDTang += double.Parse(string.IsNullOrEmpty(CanDoiKQKDTang.Rows[x]["SoTien"].ToString()) ? "0" : (CanDoiKQKDTang.Rows[x]["SoTien"].ToString()));
                        x++;
                    }
                    else
                    {
                        DataRow dr = CanDoiKQKDTang.NewRow();
                        dr["Nhom"] = NhomKQKDTang;
                        dr["HangMuc"] = "CỘNG";
                        dr["SoTien"] = TongCongKQKDTang.ToString();
                        dr["TangGiam"] = 1;
                        NhomKQKDTang = CanDoiKQKDTang.Rows[x]["Nhom"].ToString();
                        TongCongKQKDTang = double.Parse(string.IsNullOrEmpty(CanDoiKQKDTang.Rows[x]["SoTien"].ToString()) ? "0" : (CanDoiKQKDTang.Rows[x]["SoTien"].ToString()));
                        CanDoiKQKDTang.Rows.InsertAt(dr, x);
                        x = x + 2;
                    }
                }
                if (CanDoiKQKDTang.Rows.Count > 0)
                {
                    DataRow drTang;
                    drTang = CanDoiKQKDTang.NewRow();
                    drTang["Nhom"] = NhomKQKDTang;
                    drTang["HangMuc"] = "CỘNG";
                    drTang["SoTien"] = TongCongKQKDTang;
                    drTang["TangGiam"] = 1;
                    CanDoiKQKDTang.Rows.Add(drTang);
                }

                while (y < CanDoiKQKDGiam.Rows.Count)
                {
                    if (NhomKQKDGiam == CanDoiKQKDGiam.Rows[y]["Nhom"].ToString())
                    {
                        TongCongKQKDGiam += double.Parse(string.IsNullOrEmpty(CanDoiKQKDGiam.Rows[y]["SoTien"].ToString()) ? "0" : (CanDoiKQKDGiam.Rows[y]["SoTien"].ToString()));
                        y++;
                    }
                    else
                    {
                        DataRow dr = CanDoiKQKDGiam.NewRow();
                        dr["Nhom"] = NhomKQKDGiam;
                        dr["HangMuc"] = "CỘNG";
                        dr["SoTien"] = TongCongKQKDGiam.ToString();
                        dr["TangGiam"] = -1;
                        NhomKQKDGiam = CanDoiKQKDGiam.Rows[y]["Nhom"].ToString();
                        TongCongKQKDGiam = double.Parse(string.IsNullOrEmpty(CanDoiKQKDGiam.Rows[y]["SoTien"].ToString()) ? "0" : (CanDoiKQKDGiam.Rows[y]["SoTien"].ToString()));
                        CanDoiKQKDGiam.Rows.InsertAt(dr, y);
                        y = y + 2;
                    }
                }
                if (CanDoiKQKDGiam.Rows.Count > 0)
                {
                    DataRow drGiam;
                    drGiam = CanDoiKQKDGiam.NewRow();
                    drGiam["Nhom"] = NhomKQKDGiam;
                    drGiam["HangMuc"] = "CỘNG";
                    drGiam["SoTien"] = TongCongKQKDGiam;
                    drGiam["TangGiam"] = -1;
                    CanDoiKQKDGiam.Rows.Add(drGiam);
                }
                double TongCongKQKD = 0;
                if (CanDoiKQKDTang.Rows.Count > 0)
                {
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Value = "PHÁT SINH TĂNG";
