                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Font.Bold = true;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Fill.PatternType = ExcelFillStyle.Solid;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;


                    foreach (DataRow row in CanDoiKQKDTang.Rows)
                    {
                        TongCongKQKD += double.Parse(string.IsNullOrEmpty(row["SoTien"].ToString()) ? "0" : (row["SoTien"].ToString()));
