                            sheet.Cells["K" + indexKQKD + ":L" + indexKQKD].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
                        }

                        sheet.Cells["M" + indexKQKD].Value = Convert.ToDouble(row["SoTien"].ToString());
                        sheet.Cells["M" + indexKQKD].Style.Numberformat.Format = format;
                        sheet.Cells["M" + indexKQKD].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                        sheet.Cells["M" + indexKQKD].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                        sheet.Cells["M" + indexKQKD].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                        if (row["HangMuc"].ToString() == "CỘNG")
                        {
                            sheet.Cells["M" + indexKQKD].Style.Font.Bold = true;
                            sheet.Cells["M" + indexKQKD].Style.Fill.PatternType = ExcelFillStyle.Solid;
                            sheet.Cells["M" + indexKQKD].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
                        }
                    }
                }
                int k = 3;
                int cuoiTang = 3, dauTang = 3, demTang = 0;
                while (k <= CanDoiKQKDTang.Rows.Count + 2)
                {
                    if (k == CanDoiKQKDTang.Rows.Count + 2 && sheet.Cells["J" + k].Value.ToString() == sheet.Cells["J" + (k - 1)].Value.ToString())
                    {
                        var Cels = sheet.Cells["J" + dauTang + ":J" + (k)];
                        Cels.Value = sheet.Cells["J" + dauTang].Value.ToString();
                        Cels.Merge = true;
                        break;
                    }
                    else if (k == CanDoiKQKDTang.Rows.Count + 2)
                    {
                        var Celss = sheet.Cells["J" + k + ":J" + k];
                        Celss.Value = sheet.Cells["J" + dauTang].Value.ToString();
                        Celss.Merge = true;
                        break;
                    }
                    else
                    {
                        if (sheet.Cells["J" + k].Value.ToString() == sheet.Cells["J" + (k + 1)].Value.ToString())
                        {
                            cuoiTang = k + 1;
                        }
                        else
                        {
                            demTang++;
                            var Celss = sheet.Cells["J" + dauTang + ":J" + (cuoiTang)];
                            Celss.Value = sheet.Cells["J" + dauTang].Value.ToString();
                            Celss.Merge = true;
                            dauTang = cuoiTang + 1;
                            j = cuoiTang;
                            cuoiTang += demTang;
                            demTang = 0;
                        }
                        k++;
                    }
                }
                indexKQKD += 1;
                k = indexKQKD + 1;
                int temp = k;
                cuoiTang = k; dauTang = k; demTang = 0;
                if (CanDoiKQKDGiam.Rows.Count > 0)
                {
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Value = "PHÁT SINH GIẢM";
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Merge = true;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.VerticalAlignment = ExcelVerticalAlignment.Center;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Font.Bold = true;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Fill.PatternType = ExcelFillStyle.Solid;
                    sheet.Cells["J" + indexKQKD + ":M" + indexKQKD].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
