        public void ReportChiTiet()
        {
            try
            {
                var sheet = pck.Workbook.Worksheets["ChiTiet"];
                sheet.View.FreezePanes(3, 1);
                DataTable dtb = _tkknService.ReportChiTiet(ConnectionString, FromDate, ToDate);
                int i = 1;
                #region BẢNG SO SÁNH TÀI SẢN
                string Nhom = ""; double TongDauKy = 0, TongCuoiKy = 0;
                Nhom = dtb.Rows[0]["Nhom"].ToString();
                TongDauKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[0]["DauKy"].ToString()) ? "0" : (dtb.Rows[0]["DauKy"].ToString()));
                TongCuoiKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[0]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[0]["CuoiKy"].ToString()));
                while (i < dtb.Rows.Count)
                {

                    if (Nhom == dtb.Rows[i]["Nhom"].ToString())
                    {
                        TongDauKy += double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["DauKy"].ToString()) ? "0" : (dtb.Rows[i]["DauKy"].ToString()));
                        TongCuoiKy += double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[i]["CuoiKy"].ToString()));
                        i++;
                    }
                    else
                    {
                        DataRow dr;
                        dr = dtb.NewRow();
                        dr["Nhom"] = Nhom;
                        dr["ID"] = "Tổng Cộng";
                        dr["ChiTiet"] = "";
                        dr["DauKy"] = TongDauKy.ToString();
                        dr["CuoiKy"] = TongCuoiKy.ToString();
                        Nhom = dtb.Rows[i]["Nhom"].ToString();
                        TongDauKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["DauKy"].ToString()) ? "0" : (dtb.Rows[i]["DauKy"].ToString()));
                        TongCuoiKy = double.Parse(string.IsNullOrEmpty(dtb.Rows[i]["CuoiKy"].ToString()) ? "0" : (dtb.Rows[i]["CuoiKy"].ToString()));
                        dtb.Rows.InsertAt(dr, i);
                        i = i + 2;
                    }
                }
                DataRow dr1;
                dr1 = dtb.NewRow();
                dr1["Nhom"] = Nhom;
                dr1["ID"] = "Tổng Cộng";
                dr1["ChiTiet"] = "";
                dr1["DauKy"] = TongDauKy.ToString();
                dr1["CuoiKy"] = TongCuoiKy.ToString();
                dtb.Rows.Add(dr1);

                var cellE2 = sheet.Cells["F2"];
                cellE2.Value = FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
                cellE2.Style.Font.Bold = true;

                var cellF2 = sheet.Cells["G2"];
                cellF2.Value = ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                cellF2.Style.Font.Bold = true;
                int index = 3;
                double TangGiam = 0, TongTangGiam = 0, TongDauKyTotal = 0, TongCuoiKyTotal = 0;
                foreach (DataRow row in dtb.Rows)
                {
                    TongDauKyTotal += double.Parse(string.IsNullOrEmpty(row["DauKy"].ToString()) ? "0" : (row["DauKy"].ToString()));
                    TongCuoiKyTotal += double.Parse(string.IsNullOrEmpty(row["CuoiKy"].ToString()) ? "0" : (row["CuoiKy"].ToString()));
                    TangGiam = double.Parse(string.IsNullOrEmpty(row["CuoiKy"].ToString()) ? "0" : (row["CuoiKy"].ToString())) - double.Parse(string.IsNullOrEmpty(row["DauKy"].ToString()) ? "0" : (row["DauKy"].ToString()));
                    TongTangGiam += TangGiam;

                    sheet.Cells["A" + index].Value = row["Nhom"].ToString();
                    sheet.Cells["A" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["B" + index + ":D" + index].Value = row["ID"].ToString();
                    sheet.Cells["B" + index + ":D" + index].Merge = true;
                    sheet.Cells["B" + index + ":D" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["B" + index + ":D" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["E" + index].Value = row["ChiTiet"].ToString();
                    sheet.Cells["E" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["E" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;


                    sheet.Cells["F" + index].Value = Convert.ToDouble(row["DauKy"].ToString());
                    sheet.Cells["F" + index].Style.Numberformat.Format = format;
                    sheet.Cells["F" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["F" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["G" + index].Value = Convert.ToDouble(row["CuoiKy"].ToString());
                    sheet.Cells["G" + index].Style.Numberformat.Format = format;
                    sheet.Cells["G" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["G" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["H" + index].Value = TangGiam;
                    sheet.Cells["H" + index].Style.Numberformat.Format = format;
                    sheet.Cells["H" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["H" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                    index += 1;
                }
