        public void ReportThang()
        {
            try
            {
                var sheet = pck.Workbook.Worksheets["Thang"];
                sheet.Cells["A5"].Value = DateTime.Now.ToString();
                sheet.Cells["A5"].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5"].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5"].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5"].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5"].Style.Font.Bold = true;
                sheet.Cells["A5"].Style.Fill.PatternType = ExcelFillStyle.Solid;
                sheet.Cells["A5"].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Coral);
            }
            catch (Exception ex)
            {
                _log4net.Error(ex);
            }
        }

        public ActionResult BCKiemToan_KetQuaKinhDoanh(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtb = _tkknService.ReportKQKD(ConnectionString, FromDate, ToDate);

            DataView dtvCKD = dtb.DefaultView;
            dtvCKD.RowFilter = "XuatXu = 'CKD'";
            DataTable dtbCKD = dtvCKD.ToTable();

            DataView dtvCBU = dtb.DefaultView;
            dtvCBU.RowFilter = "XuatXu = 'CBU'";
            DataTable dtbCBU = dtvCBU.ToTable();

            DataView dtvLe = dtb.DefaultView;
            dtvLe.RowFilter = "VayNH = '0'";
            DataTable dtbLe = dtvLe.ToTable();

            DataView dtvGop = dtb.DefaultView;
            dtvGop.RowFilter = "VayNH > '0'";
            DataTable dtbGop = dtvGop.ToTable();

            string From = FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            string To = ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            //phan le va gop



            ViewBag.From = From;
            ViewBag.To = To;
            ViewBag.dtbCKD = dtbCKD;
            ViewBag.dtbCBU = dtbCBU;
            ViewBag.dtbLe = dtbLe;
            ViewBag.dtbGop = dtbGop;
            return PartialView();
        }

