        public ActionResult BCNTHBH(DateTime FromDate, DateTime ToDate)
        {
            DataTable DebtCollection = _tkknService.BCNoTHBH(ConnectionString, FromDate, ToDate);
            DataTable Promotioninsurance = _tkknService.BCNoBHKM(ConnectionString, FromDate, ToDate);
            DataTable NoHHBH_TH = _tkknService.BCNoHHBH(ConnectionString, FromDate, ToDate, "NTHBH");
            DataTable NoHHBH_KM = _tkknService.BCNoHHBH(ConnectionString, FromDate, ToDate, "NBHBX");
            ViewBag.ToDate = ToDate;
            ViewBag.FromDate = FromDate;
            ViewBag.ListBCNTHBH = DebtCollection;
            ViewBag.ListBCNBHKM = Promotioninsurance;
            ViewBag.ListNoHHBH_TH = NoHHBH_TH;
            ViewBag.ListNoHHBH_KM = NoHHBH_KM;
            TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            return PartialView(DebtCollection);
        }
        public ActionResult BCNGHBH(DateTime FromDate, DateTime ToDate)
        {
            DataTable ListNoGHBH = _tkknService.BCNoGHBN(ConnectionString, FromDate, ToDate);
            DataTable ListGHBHK = _tkknService.BCNoGHBHK(ConnectionString, FromDate, ToDate);
