        public ActionResult BCNoThuHHHB(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtResult = _tkknService.BCNoThuHHHB(ConnectionString, FromDate, ToDate);
            //TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
            TuNgayDenNgay += "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            return PartialView(dtResult);
        }
