        public ActionResult BCNPTraKhac(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbResult = _tkknService.BCNPTraKhac(ConnectionString, FromDate, ToDate);
            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;

            string KH = ""; double TongSoTien = 0, TongThanhToan = 0, TongConLai = 0;
            KH = dtbResult.Rows[0]["DienGiai"].ToString();
            TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienNo"].ToString()));
            TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienDaTra"].ToString()));
            TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienConLai"].ToString()));
            int i = 1;
            while (i < dtbResult.Rows.Count)
            {

                if (KH == dtbResult.Rows[i]["DienGiai"].ToString())
                {
                    TongSoTien += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                    TongThanhToan += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                    TongConLai += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));
                    i++;
                }
                else
                {
                    DataRow dr;
                    dr = dtbResult.NewRow();
                    dr["DienGiai"] = KH;
                    dr["TenDoiTac"] = "Tổng Cộng";
                    dr["GhiChu"] = "Tổng Cộng";
                    dr["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
                    dr["SoTienNo"] = TongSoTien;
                    dr["SoTienDaTra"] = TongThanhToan;
                    dr["SoTienConLai"] = TongConLai.ToString();
                    KH = dtbResult.Rows[i]["DienGiai"].ToString();
                    TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                    TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                    TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));
                    dtbResult.Rows.InsertAt(dr, i);
                    i = i + 2;
                }
            }
            DataRow dr1;
            dr1 = dtbResult.NewRow();
            dr1["DienGiai"] = KH;
            dr1["TenDoiTac"] = "Tổng Cộng";
            dr1["GhiChu"] = "Tổng Cộng";
            dr1["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
            dr1["SoTienNo"] = TongSoTien;
            dr1["SoTienDaTra"] = TongThanhToan;
            dr1["SoTienConLai"] = TongConLai.ToString();
            dtbResult.Rows.Add(dr1);

            return PartialView(dtbResult);
        }
