        public ActionResult BCThuHoXang(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbResult = _tkknService.BCNgayThuHoXang(ConnectionString, FromDate, ToDate);
            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;

            string KH = ""; double TongSoTien = 0, TongThanhToan = 0, TongConLai = 0, TotalTongSoTien = 0, TotalTongThanhToan = 0, TotalTongConLai = 0;
            KH = dtbResult.Rows[0]["DonViNo"].ToString();
            TotalTongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienNo"].ToString()));
            TotalTongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienDaTra"].ToString()));
            TotalTongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienConLai"].ToString()));

            TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienNo"].ToString()));
            TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienDaTra"].ToString()));
            TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienConLai"].ToString()));
            int i = 1;
            while (i < dtbResult.Rows.Count)
            {
                TotalTongSoTien += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                TotalTongThanhToan += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                TotalTongConLai += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));

                if (KH == dtbResult.Rows[i]["DonViNo"].ToString())
                {
                    TongSoTien += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                    TongThanhToan += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                    TongConLai += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));
                    i++;
                }
                else
                {
                    DataRow dr;
                    dr = dtbResult.NewRow();
                    dr["DonViNo"] = "TỔNG CỘNG THU HỘ " + KH.ToUpper();
                    /*flag = dr["DonViNo"].ToString();*/
                    //dr["NoiDung"] = "Tổng Cộng";
                    dr["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
                    dr["SoTienNo"] = TongSoTien;
                    dr["SoTienDaTra"] = TongThanhToan;
                    dr["SoTienConLai"] = TongConLai.ToString();


                    //chuyen qua loai khach hang ke tiep
                    KH = dtbResult.Rows[i]["DonViNo"].ToString();
                    TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                    TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                    TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));
                    dtbResult.Rows.InsertAt(dr, i);
                    i = i + 2;
                }
            }
            if (dtbResult.Rows.Count > 0)
            {
                DataRow dr;
                dr = dtbResult.NewRow();
                dr["DonViNo"] = "TỔNG CỘNG THU HỘ " + KH.ToUpper();
                /*flag = dr["DonViNo"].ToString();*/
                //dr["NoiDung"] = "Tổng Cộng";
                dr["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
                dr["SoTienNo"] = TongSoTien;
                dr["SoTienDaTra"] = TongThanhToan;
                dr["SoTienConLai"] = TongConLai.ToString();
                dtbResult.Rows.Add(dr);
            }
            DataRow dr1;
            dr1 = dtbResult.NewRow();
            dr1["DonViNo"] = "TỔNG CỘNG";
            //dr1["NoiDung"] = "Tổng Cộng";
            dr1["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
            dr1["SoTienNo"] = TotalTongSoTien;
            dr1["SoTienDaTra"] = TotalTongThanhToan;
            dr1["SoTienConLai"] = TotalTongConLai.ToString();
            dtbResult.Rows.Add(dr1);

            return PartialView(dtbResult);
        }


        public ActionResult BCNoMuaPTPK(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbResult = _tkknService.BCNoMuaPTPK(ConnectionString, FromDate, ToDate);
            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;

            string KH = ""; double TongSoTien = 0, TongThanhToan = 0, TongConLai = 0;
            double TongTienTotal = 0, TongThanhToanTotal = 0, TongConLaiTotal = 0;
            KH = dtbResult.Rows[0]["TenDoiTac"].ToString();
            TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienNo"].ToString()));
            TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienDaTra"].ToString()));
            TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienConLai"].ToString()));
            int i = 1;
            while (i < dtbResult.Rows.Count)
            {

                if (KH == dtbResult.Rows[i]["TenDoiTac"].ToString())
                {
                    TongSoTien += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                    TongThanhToan += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                    TongConLai += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));

                    i++;
                }
                else
                {
                    DataRow dr;
                    dr = dtbResult.NewRow();
                    dr["DonViNo"] = "TỔNG CỘNG " + KH;
                    dr["Hoten"] = "TỔNG";
                    /*flag = dr["DonViNo"].ToString();*/
                    //dr["NoiDung"] = "Tổng Cộng";
                    dr["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
                    dr["SoTienNo"] = Math.Round(TongSoTien);
                    dr["SoTienDaTra"] = Math.Round(TongThanhToan);
                    dr["SoTienConLai"] = Math.Round(TongConLai);
                    KH = dtbResult.Rows[i]["TenDoiTac"].ToString();
                    TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                    TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                    TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));
                    dtbResult.Rows.InsertAt(dr, i);
                    i = i + 2;
                }
            }
            DataRow dr1;
            dr1 = dtbResult.NewRow();
            dr1["DonViNo"] = "TỔNG CỘNG " + KH;
            //dr1["NoiDung"] = "Tổng Cộng";
            dr1["Hoten"] = "TỔNG";
            dr1["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
            dr1["SoTienNo"] = Math.Round(TongSoTien);
            dr1["SoTienDaTra"] = Math.Round(TongThanhToan);
            dr1["SoTienConLai"] = Math.Round(TongConLai);
            dtbResult.Rows.Add(dr1);

            for (int j = 0; j < dtbResult.Rows.Count; j++)
            {
                if (dtbResult.Rows[j]["Hoten"].ToString() == "TỔNG")
                {
                    TongTienTotal += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[j]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[j]["SoTienNo"].ToString()));
                    TongThanhToanTotal += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[j]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[j]["SoTienDaTra"].ToString()));
                    TongConLaiTotal += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[j]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[j]["SoTienConLai"].ToString()));
                }
            }


            DataRow dr2;
            dr2 = dtbResult.NewRow();
            dr2["DonViNo"] = "TỔNG CỘNG";
            dr2["Hoten"] = "Tổng Cộng Tất Cả";
            dr2["NgayNo"] = DateTime.Now.ToString("dd/MM/yyyy");
            dr2["SoTienNo"] = Math.Round(TongTienTotal);
            dr2["SoTienDaTra"] = Math.Round(TongThanhToanTotal);
            dr2["SoTienConLai"] = Math.Round(TongConLaiTotal);
            dtbResult.Rows.Add(dr2);

            return PartialView(dtbResult);
        }

