        public void ReportBCNPTraKhac()
        {
            try
            {

                DataTable dtbResult = _tkknService.BCNPTraKhac(ConnectionString, FromDate, ToDate);
                ViewBag.FromDate = FromDate;
                ViewBag.ToDate = ToDate;
                TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                ViewBag.TuNgayDenNgay = TuNgayDenNgay;

                string KH = ""; double TongSoTien = 0, TongThanhToan = 0, TongConLai = 0;
                dtbResult.Columns.Add("STT", typeof(string));
                dtbResult.Rows[0]["STT"] = 1;

                List<int> lstsumrow = new List<int>();
                KH = dtbResult.Rows[0]["DienGiai"].ToString();
                TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienNo"].ToString()));
                TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienDaTra"].ToString()));
                TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienConLai"].ToString()));
                int i = 1, stt = 2;
                while (i < dtbResult.Rows.Count)
                {

                    if (KH == dtbResult.Rows[i]["DienGiai"].ToString())
                    {
                        dtbResult.Rows[i]["STT"] = stt;
                        TongSoTien += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                        TongThanhToan += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                        TongConLai += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));
                        i++; stt++;
                    }
                    else
                    {
                        DataRow dr;
                        dr = dtbResult.NewRow();
                        dr["STT"] = KH;
                        dr["SoTienNo"] = TongSoTien;
                        dr["SoTienDaTra"] = TongThanhToan;
                        dr["SoTienConLai"] = TongConLai.ToString();

                        KH = dtbResult.Rows[i]["DienGiai"].ToString();
                        TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienNo"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienNo"].ToString()));
                        TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienDaTra"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienDaTra"].ToString()));
                        TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienConLai"].ToString()));
                        dtbResult.Rows.InsertAt(dr, i);
                        dtbResult.Rows[i + 1]["STT"] = stt;
                        lstsumrow.Add(i);
                        i = i + 2; stt++;
                    }
                }
                DataRow dr1;
                dr1 = dtbResult.NewRow();
                dr1["STT"] = KH;

                dr1["SoTienNo"] = TongSoTien;
                dr1["SoTienDaTra"] = TongThanhToan;
                dr1["SoTienConLai"] = TongConLai.ToString();
                dtbResult.Rows.Add(dr1);
                lstsumrow.Add(dtbResult.Rows.Count - 1);
                List<string> lstcol = new List<string>() { "STT", "NgayNo", "TenDoiTac", "GhiChu", "SoTienNo", "SoTienDaTra", "SoTienConLai", "NgayThanhToan", "LyDoChi" };
                for (i = 0; i < lstcol.Count; i++)
                {
                    dtbResult.Columns[lstcol[i]].SetOrdinal(i);
                }
                for (i = dtbResult.Columns.Count - 1; i >= lstcol.Count; i--)
                {
                    dtbResult.Columns.RemoveAt(i);
                }
                //phần excel
                var sheet = pck.Workbook.Worksheets["Nợ Phải Trả Khác"];
                sheet.View.FreezePanes(4, 1);
                Color colorSum = System.Drawing.ColorTranslator.FromHtml("#DEB887");
                try
                {
                    sheet.Cells["A1:I1"].Value = "DANH SÁCH CHI TIẾT CÔNG NỢ PHẢI TRẢ KHÁC " + ShowRoom;
                    sheet.Cells["A2:I2"].Value = TuNgayDenNgay;
                    sheet.Cells["A4"].LoadFromDataTable(dtbResult, false);
                    sheet.Cells["A4" + ":I" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":I" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":I" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":I" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["E4:G" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Numberformat.Format = format;
                    foreach (int idex in lstsumrow)
                    {
                        int col = idex + 4;
                        sheet.Cells["A" + col + ":D" + col].Merge = true;
                        sheet.Cells["A" + col + ":I" + col].Style.Fill.PatternType = ExcelFillStyle.Solid;
                        sheet.Cells["A" + col + ":I" + col].Style.Fill.BackgroundColor.SetColor(colorSum);
                        sheet.Cells["A" + col + ":I" + col].Style.Font.Bold = true;
                    }
                }
                catch (Exception ex)
                {
                    sheet.Cells["A3:A4"].Value = "Lỗi báo cáo" + ex.Message + ". " + ex.InnerException;
                    _log4net.Error(ex);
                }
            }
            catch (Exception ex)
            {
                log.Error(ex);
            }
        }
        public void Report_NBDTK()
        {
            try
            {

                DataTable dtbResult = _tkknService.BCNPTraKhac_NBDTK(ConnectionString, FromDate, ToDate);
                ViewBag.FromDate = FromDate;
