                {
                    sheet.Cells["A1:H1"].Value = "DANH SÁCH CHI TIẾT CÔNG NỢ BẢO DƯỠNG TIẾT KIỆM " + ShowRoom;
                    sheet.Cells["A2:H2"].Value = TuNgayDenNgay;
                    sheet.Cells["A4"].LoadFromDataTable(dtbResult, false);
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["E4:G" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Numberformat.Format = format;
                    foreach (int idex in lstsumrow)
                    {
                        int col = idex + 4;
                        sheet.Cells["A" + col].Value = "TỔNG CỘNG";
                        sheet.Cells["A" + col + ":D" + col].Merge = true;
                        sheet.Cells["A" + col + ":K" + col].Style.Fill.PatternType = ExcelFillStyle.Solid;
                        sheet.Cells["A" + col + ":K" + col].Style.Fill.BackgroundColor.SetColor(colorSum);
                        sheet.Cells["A" + col + ":K" + col].Style.Font.Bold = true;
                    }
                }
                catch (Exception ex)
                {
                    sheet.Cells["A3:A4"].Value = "Lỗi báo cáo" + ex.Message + ". " + ex.InnerException;
                    _log4net.Error(ex);
                }
            }
            catch (Exception ex)
            {
                log.Error(ex);
            }
        }
