        public ActionResult BCChiTietCoc(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbResult = _tkknService.BCChiTietCoc(ConnectionString, FromDate, ToDate);
            ViewBag.FromDate = FromDate;
            ViewBag.ToDate = ToDate;
            TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;

            string MaLoaiPhieu = ""; double TongSoTien = 0, TongThanhToan = 0, TongConLai = 0;
            double TongTienTotal = 0, TongThanhToanTotal = 0, TongConLaiTotal = 0;

            MaLoaiPhieu = dtbResult.Rows[0]["MaLoaiPhieu"].ToString();
            TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["TongCong"].ToString()) ? "0" : (dtbResult.Rows[0]["TongCong"].ToString()));
            TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["SoTienChi"].ToString()) ? "0" : (dtbResult.Rows[0]["SoTienChi"].ToString()));
            TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[0]["ConLai"].ToString()) ? "0" : (dtbResult.Rows[0]["ConLai"].ToString()));
            int i = 1;
            string TenLoaiPhieu = "";
            while (i < dtbResult.Rows.Count)
            {
                switch (MaLoaiPhieu)
                {
                    case "CCOMX": TenLoaiPhieu = "CHI ĐẶT CỌC MUA XE"; break;
                    case "CDACO": TenLoaiPhieu = "CHI ĐẶT CỌC MUA TÀI SẢN"; break;
                    case "CCOPT": TenLoaiPhieu = "CHI ĐẶT CỌC MUA PHỤ TÙNG"; break;
                    case "CCOTH": TenLoaiPhieu = "CHI ĐẶT CỌC TỔNG HỢP"; break;
                    case "CCOGC": TenLoaiPhieu = "CHI ĐẶT CỌC GIA CÔNG NGOÀI"; break;
                    default: break;
                }
                if (MaLoaiPhieu == dtbResult.Rows[i]["MaLoaiPhieu"].ToString())
                {
                    TongSoTien += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["TongCong"].ToString()) ? "0" : (dtbResult.Rows[i]["TongCong"].ToString()));
                    TongThanhToan += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienChi"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienChi"].ToString()));
                    TongConLai += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["ConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["ConLai"].ToString()));

                    i++;
                }
                else
                {
                    DataRow dr;
                    dr = dtbResult.NewRow();
                    dr["MaLoaiPhieu"] = "TỔNG CỘNG " + TenLoaiPhieu;
                    dr["NgayChi"] = "";
                    /*flag = dr["DonViNo"].ToString();*/
                    dr["NgaySuDungCoc"] = "";
                    dr["TenDoiTac"] = "";
                    dr["NoiDung"] = "TỔNG";
                    dr["TongCong"] = Math.Round(TongSoTien);
                    dr["SoTienChi"] = Math.Round(TongThanhToan);
                    dr["ConLai"] = Math.Round(TongConLai);
                    MaLoaiPhieu = dtbResult.Rows[i]["MaLoaiPhieu"].ToString();
                    TongSoTien = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["TongCong"].ToString()) ? "0" : (dtbResult.Rows[i]["TongCong"].ToString()));
                    TongThanhToan = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["SoTienChi"].ToString()) ? "0" : (dtbResult.Rows[i]["SoTienChi"].ToString()));
                    TongConLai = double.Parse(string.IsNullOrEmpty(dtbResult.Rows[i]["ConLai"].ToString()) ? "0" : (dtbResult.Rows[i]["ConLai"].ToString()));
                    dtbResult.Rows.InsertAt(dr, i);
                    i = i + 2;
                }
            }
            switch (MaLoaiPhieu)
            {
                case "CCOMX": TenLoaiPhieu = "CHI ĐẶT CỌC MUA XE"; break;
                case "CDACO": TenLoaiPhieu = "CHI ĐẶT CỌC MUA TÀI SẢN"; break;
                case "CCOPT": TenLoaiPhieu = "CHI ĐẶT CỌC MUA PHỤ TÙNG"; break;
                case "CCOTH": TenLoaiPhieu = "CHI ĐẶT CỌC TỔNG HỢP"; break;
                case "CCOGC": TenLoaiPhieu = "CHI ĐẶT CỌC GIA CÔNG NGOÀI"; break;
                default: break;
            }
            DataRow dr1;
            dr1 = dtbResult.NewRow();
            dr1["MaLoaiPhieu"] = "TỔNG CỘNG " + TenLoaiPhieu;
            dr1["NgayChi"] = "";
            dr1["TenDoiTac"] = "";
            dr1["NoiDung"] = "TỔNG";
            dr1["NgaySuDungCoc"] = "";
            dr1["TongCong"] = Math.Round(TongSoTien);
            dr1["SoTienChi"] = Math.Round(TongThanhToan);
            dr1["ConLai"] = Math.Round(TongConLai);
            dtbResult.Rows.Add(dr1);

            for (int j = 0; j < dtbResult.Rows.Count; j++)
            {
                if (dtbResult.Rows[j]["NoiDung"].ToString() == "TỔNG")
                {
                    TongTienTotal += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[j]["TongCong"].ToString()) ? "0" : (dtbResult.Rows[j]["TongCong"].ToString()));
                    TongThanhToanTotal += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[j]["SoTienChi"].ToString()) ? "0" : (dtbResult.Rows[j]["SoTienChi"].ToString()));
                    TongConLaiTotal += double.Parse(string.IsNullOrEmpty(dtbResult.Rows[j]["ConLai"].ToString()) ? "0" : (dtbResult.Rows[j]["ConLai"].ToString()));
                }
            }


            DataRow dr2;
            dr2 = dtbResult.NewRow();
            dr2["MaLoaiPhieu"] = "TỔNG CỘNG";
            dr2["NoiDung"] = "Tổng Cộng Tất Cả";
            dr2["NgayChi"] = "";
            dr2["TenDoiTac"] = "";
            dr2["NgaySuDungCoc"] = "";
            dr2["TongCong"] = Math.Round(TongTienTotal);
            dr2["SoTienChi"] = Math.Round(TongThanhToanTotal);
            dr2["ConLai"] = Math.Round(TongConLaiTotal);
            dtbResult.Rows.Add(dr2);


            return PartialView(dtbResult);
        }
