        public ActionResult BCVonTaiSan(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtTienDauTu = _tkknService.BCTienDauTu(ConnectionString, FromDate, ToDate);
            DataTable dtKhoTaiSan = _tkknService.BCKhoTaiSan(ConnectionString, FromDate, ToDate);
            DataTable dtDauTuDuAn = _tkknService.BCDauTuDuAn(FromDate, ToDate);
            TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.ToDate = TuNgayDenNgay;
            ViewBag.dtKhoTaiSan = dtKhoTaiSan;
            ViewBag.dtTienDauTu = dtTienDauTu;
            ViewBag.dtDauTuDuAn = dtDauTuDuAn;
            return PartialView();
        }
