        #region Bao cao BPTC
        public ActionResult ReportAll_BPTC(DateTime FromDate, DateTime ToDate)
        {
            try
            {
                this.FromDate = FromDate;
                this.ToDate = ToDate;
                //var str = CacheKey.keyExcelTotal
                TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
                TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                DenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;

                string str = Server.MapPath("~\\Views\\FileMau\\Template_BaoCaoPTC.xlsx");
                FileInfo template = new FileInfo(str);
                pck = new ExcelPackage(new FileInfo(str));

                string strFileName = "Bao cao Phong Tai chinh " + FromDate.ToString("dd.MM.yyyy") + "_" + ToDate.ToString("dd.MM.yyyy") + "-" + DateTime.Now.ToString("hhMMssfff") + ".xlsx";

                #region Report All Sheet
                //ReportBCBPTC_CNBHDVTheoDoiTac();
                ReportBCBPTC_CNBHDVChiTiet();
                //ReportBCBPTC_CNBHDVTheoLyDoQuaHan();
                ReportBCBPTC_SoatXetChungTu();
                ReportBCBPTC_THCTBanXe();
                #endregion Report All Sheet


                return new ExcelInsuranceDownload(pck, strFileName);
            }
            catch (Exception ex)
            {
                _log4net.Error(ex);
            }
            return View();
        }

        public void ReportBCBPTC_CNBHDVChiTiet()
        {
            DateTime start = new DateTime();

            var sheet = pck.Workbook.Worksheets["CNBHDV-ChiTiet"];

            try
            {
                //   _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")BCBPTC_CNBHDVChiTiet");

                DataSet dsResult = _tkknService.BCBPTC_CNBHDVChiTiet(ConnectionString, ToDate);
                DataTable dtbResult = dsResult.Tables[0];
                DataTable dtbNoKhachLe = dsResult.Tables[1];
                DataTable dtbCongNoQuaHan = dsResult.Tables[2];
                DataTable dtbCongNoTheoDoiTac = dsResult.Tables[3];

                // dtbResult.Columns.In("STT");
                // dtbNoKhachLe.Columns.Add("STT");
                int index = 6;
                Double tongGiaTriCongNo = 0, tongSoTienThanhToan = 0, tongSoTienNo = 0, tongSoNgayCongNo = 0, tongTongThoiGian = 0, tongSoNgayTrangThai = 0;


                foreach (DataRow row in dtbResult.Rows)
                {
                    //stt++;
                    //row["STT"] = stt;
                    tongGiaTriCongNo += row["GiaTriCongNo"].ToString() == "" ? 0 : Convert.ToDouble(row["GiaTriCongNo"]);
                    tongSoTienThanhToan += row["SoTienThanhToan"].ToString() == "" ? 0 : Convert.ToDouble(row["SoTienThanhToan"]);
                    tongSoTienNo += row["SoTienNo"].ToString() == "" ? 0 : Convert.ToDouble(row["SoTienNo"]);
                    tongSoNgayCongNo += row["SoNgayCongNo"].ToString() == "" ? 0 : Convert.ToDouble(row["SoNgayCongNo"]);
                    tongTongThoiGian += row["TongThoiGian"].ToString() == "" ? 0 : Convert.ToDouble(row["TongThoiGian"]);
                    tongSoNgayTrangThai += row["SoNgayTrangThai"].ToString() == "" ? 0 : Convert.ToDouble(row["SoNgayTrangThai"]);

                }
                DataRow r = dtbResult.NewRow();
                r["STT"] = "A-TỔNG NỢ BẢO HIỂM";
                r["GiaTriCongNo"] = tongGiaTriCongNo;
                r["SoTienThanhToan"] = tongSoTienThanhToan;
                r["SoTienNo"] = tongSoTienNo;
                r["SoNgayCongNo"] = tongSoNgayCongNo;
                r["TongThoiGian"] = tongTongThoiGian;
                r["SoNgayTrangThai"] = tongSoNgayTrangThai;

                dtbResult.Rows.InsertAt(r, 0);

                sheet.Cells["A5"].LoadFromDataTable(dtbResult, false);



                //index += 1;
                //index = dtbResult.Rows.Count + 4;
                index = 5;

                string DenNgay = "Ngày báo cáo:" + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                //phan fromdate và todate
                sheet.Cells["A2"].Value = DenNgay;

                sheet.Cells["A5:D5"].Merge = true;
                sheet.Cells["A5:W5"].Style.Font.Bold = true;
                sheet.Cells["A5:D5"].Style.HorizontalAlignment = ExcelHorizontalAlignment.Right;

                sheet.Cells["A5" + ":W" + index].Style.Border.BorderAround(ExcelBorderStyle.Thin);
                sheet.Cells["A5" + ":W" + index].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":W" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":W" + index].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":W" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                sheet.Cells.AutoFitColumns();

                //stt = 1;
                Double tongGiaTriCongNoKL = 0, tongSoTienThanhToanKL = 0, tongSoTienNoKL = 0, tongSoNgayCongNoKL = 0
                    , tongTongThoiGianKL = 0, tongSoNgayTrangThaiKL = 0;

                foreach (DataRow r1 in dtbNoKhachLe.Rows)
                {
                    // r1["STT"] = stt++;
                    tongGiaTriCongNoKL += r1["GiaTriCongNo"].ToString() == "" ? 0 : Convert.ToDouble(r1["GiaTriCongNo"]);
                    tongSoTienThanhToanKL += r1["SoTienThanhToan"].ToString() == "" ? 0 : Convert.ToDouble(r1["SoTienThanhToan"]);
                    tongSoTienNoKL += r1["SoTienNo"].ToString() == "" ? 0 : Convert.ToDouble(r1["SoTienNo"]);
                    tongSoNgayCongNoKL += r1["SoNgayCongNo"].ToString() == "" ? 0 : Convert.ToDouble(r1["SoNgayCongNo"]);
                    tongTongThoiGianKL += r1["TongThoiGian"].ToString() == "" ? 0 : Convert.ToDouble(r1["TongThoiGian"]);
                    tongSoNgayTrangThaiKL += r1["SoNgayTrangThai"].ToString() == "" ? 0 : Convert.ToDouble(r1["SoNgayTrangThai"]);
                }

                DataRow rTongKL = dtbNoKhachLe.NewRow();
                rTongKL["STT"] = "B-TỔNG NỢ KHÁCH LẺ";
                rTongKL["GiaTriCongNo"] = tongGiaTriCongNoKL;
                rTongKL["SoTienThanhToan"] = tongSoTienThanhToanKL;
                rTongKL["SoTienNo"] = tongSoTienNoKL;
                rTongKL["SoNgayCongNo"] = tongSoNgayCongNoKL;
                rTongKL["TongThoiGian"] = tongTongThoiGianKL;
                rTongKL["SoNgayTrangThai"] = tongSoNgayTrangThaiKL;

                dtbNoKhachLe.Rows.InsertAt(rTongKL, 0);

                //index = dtbResult.Rows.Count + 4 + dtbNoKhachLe.Rows.Count;
                index = dtbResult.Rows.Count + 5;// + dtbNoKhachLe.Rows.Count;

                sheet.Cells["A" + (dtbResult.Rows.Count + 5)].LoadFromDataTable(dtbNoKhachLe, false);

                sheet.Cells["A" + index + ":D" + index].Merge = true;
                sheet.Cells["A" + index + ":W" + index].Style.Font.Bold = true;
                sheet.Cells["A" + index + ":D" + index].Style.HorizontalAlignment = ExcelHorizontalAlignment.Right;

                index = index + dtbNoKhachLe.Rows.Count;

                sheet.Cells["A5" + ":W" + index].Style.Border.BorderAround(ExcelBorderStyle.Thin);
                sheet.Cells["A5" + ":W" + index].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":W" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":W" + index].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":W" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;




                //  _log4net.End("(" + CurrentUser.UserName + ")(" + ShowRoom + ")End C# BCBPTC_CNBHDVChiTiet");
                DateTime end = DateTime.Now;

                ReportBCBPTC_CNBHDVTheoLyDoQuaHan(dtbCongNoQuaHan);
                ReportBCBPTC_CNBHDVTheoDoiTac(dtbCongNoTheoDoiTac);
                //  this.AddActionLog(CurrentUser.UserName, "Report", "BCBPTC_CNBHDVChiTiet", start, end, "");
            }
            catch (Exception ex)
            {
                sheet.Cells["A3:A4"].Value = "Lỗi báo cáo" + ex.Message + ". " + ex.InnerException;
                //   _log4net.Error(ex);
                DateTime end = DateTime.Now;
                //   this.AddActionLog(CurrentUser.UserName, "Report", "BCBPTC_CNBHDVChiTiet", start, end, ex);
            }



        }

