        public void ReportBCBPTC_CNBHDVTheoDoiTac(DataTable dtbResult)
        {
            DateTime start = new DateTime();

            var sheet = pck.Workbook.Worksheets["CNBHDV-DoiTac"];

            try
            {
                //  _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")BCBPTC_CNBHDVTheoDoiTac");

                //DataTable dtbResult = _tkknService.BCBPTC_CNBHDVTheoDoiTac( ToDate);


                DateTime FromDate = DateTime.Parse(ToDate.ToString("yyyy-MM-01"));


                dtbResult.Columns.Add("STT");
                int index = 6;
                Double totalDuNoTichLuy = 0,
                   totalPhatSinhTuDauThang = 0,
                   totalDaThanhToanTuDauThang = 0,
                   totalCongNoConLai = 0,
                   totalCHT_TH = 0,
                   totalCHT_QH = 0,
                   totalXNCN_TH = 0,
                   totalXNCN_QH = 0,
                   totalCN_TH = 0,
                   totalCN_QH = 0,
                   totalKLCHT_TH = 0,
                   totalKLCHT_QH = 0,
                   totalKLXNCN_TH = 0,
                   totalKLXNCN_QH = 0,
                   totalKLCN_TH = 0,
                   totalKLCN_QH = 0;

                List<string> lstcolumn = new List<string>();
                lstcolumn.Add("Loai");
                lstcolumn.Add("STT");
                lstcolumn.Add("TenDoiTac");
                lstcolumn.Add("DuNoTichLuy");
                lstcolumn.Add("PhatSinhTuDauThang");
                lstcolumn.Add("DaThanhToanTuDauThang");
                lstcolumn.Add("CongNoConLai");
                lstcolumn.Add("CHT_TH");
                lstcolumn.Add("CHT_QH");
                lstcolumn.Add("XNCN_TH");
                lstcolumn.Add("XNCN_QH");
                lstcolumn.Add("CN_TH");
                lstcolumn.Add("CN_QH");

                int stt = 0;
                //sap xep lai thu tu cot
                for (int i = 0; i < lstcolumn.Count; i++)
                {
                    dtbResult.Columns[lstcolumn[i]].SetOrdinal(i);
                }
                for (int i = dtbResult.Columns.Count - 1; i >= lstcolumn.Count; i--)
                {
                    dtbResult.Columns.RemoveAt(i);
                }

                dtbResult.DefaultView.RowFilter = "Loai ='BH'";
                DataTable dtbBaoHiem = dtbResult.DefaultView.ToTable();

                dtbResult.DefaultView.RowFilter = "Loai ='KL'";
                DataTable dtbNoKhachLe = dtbResult.DefaultView.ToTable();

                dtbBaoHiem.Columns.Remove("Loai");
                dtbNoKhachLe.Columns.Remove("Loai");
                foreach (DataRow row in dtbBaoHiem.Rows)
                {
                    stt++;
                    row["STT"] = stt;
                    totalDuNoTichLuy += row["DuNoTichLuy"].ToString() == "" ? 0 : Convert.ToDouble(row["DuNoTichLuy"].ToString());
                    totalPhatSinhTuDauThang += row["PhatSinhTuDauThang"].ToString() == "" ? 0 : Convert.ToDouble(row["PhatSinhTuDauThang"].ToString());
                    totalDaThanhToanTuDauThang += row["DaThanhToanTuDauThang"].ToString() == "" ? 0 : Convert.ToDouble(row["DaThanhToanTuDauThang"].ToString());
                    totalCongNoConLai += row["CongNoConLai"].ToString() == "" ? 0 : Convert.ToDouble(row["CongNoConLai"].ToString());
                    totalCHT_TH += row["CHT_TH"].ToString() == "" ? 0 : Convert.ToDouble(row["CHT_TH"].ToString());
                    totalCHT_QH += row["CHT_QH"].ToString() == "" ? 0 : Convert.ToDouble(row["CHT_QH"].ToString());
                    totalXNCN_TH += row["XNCN_TH"].ToString() == "" ? 0 : Convert.ToDouble(row["XNCN_TH"].ToString());
                    totalXNCN_QH += row["XNCN_QH"].ToString() == "" ? 0 : Convert.ToDouble(row["XNCN_QH"].ToString());
                    totalCN_TH += row["CN_TH"].ToString() == "" ? 0 : Convert.ToDouble(row["CN_TH"].ToString());
                    totalCN_QH += row["CN_QH"].ToString() == "" ? 0 : Convert.ToDouble(row["CN_QH"].ToString());

                }
                DataRow r = dtbBaoHiem.NewRow();
                r["STT"] = "";
                r["TenDoiTac"] = "A-TỔNG NỢ BẢO HIỂM";
                r["DuNoTichLuy"] = totalDuNoTichLuy;
                r["PhatSinhTuDauThang"] = totalPhatSinhTuDauThang;
                r["DaThanhToanTuDauThang"] = totalDaThanhToanTuDauThang;
                r["CongNoConLai"] = totalCongNoConLai;
                r["CHT_TH"] = totalCHT_TH;
                r["CHT_QH"] = totalCHT_QH;
                r["XNCN_TH"] = totalXNCN_TH;
                r["XNCN_QH"] = totalXNCN_QH;
                r["CN_TH"] = totalCN_TH;
                r["CN_QH"] = totalCN_QH;

                dtbBaoHiem.Rows.InsertAt(r, 0);
                //tinh toán tổng nợ khách lẻ
                float totalDuNoTichLuyKL = 0;
                float totalPhatSinhTuDauThangKL = 0;
                float totalDaThanhToanTuDauThangKL = 0;
                float totalCongNoConLaiKL = 0;
                foreach (DataRow r1 in dtbNoKhachLe.Rows)
                {
                    totalDuNoTichLuyKL += float.Parse(r1["DuNoTichLuy"].ToString());
                    totalPhatSinhTuDauThangKL += float.Parse(r1["PhatSinhTuDauThang"].ToString());
                    totalDaThanhToanTuDauThangKL += float.Parse(r1["DaThanhToanTuDauThang"].ToString());
                    totalCongNoConLaiKL += float.Parse(r1["CongNoConLai"].ToString());

                    totalKLCHT_TH += r1["CHT_TH"].ToString() == "" ? 0 : Convert.ToDouble(r1["CHT_TH"].ToString());
                    totalKLCHT_QH += r1["CHT_QH"].ToString() == "" ? 0 : Convert.ToDouble(r1["CHT_QH"].ToString());
                    totalKLXNCN_TH += r1["XNCN_TH"].ToString() == "" ? 0 : Convert.ToDouble(r1["XNCN_TH"].ToString());
                    totalKLXNCN_QH += r1["XNCN_QH"].ToString() == "" ? 0 : Convert.ToDouble(r1["XNCN_QH"].ToString());
                    totalKLCN_TH += r1["CN_TH"].ToString() == "" ? 0 : Convert.ToDouble(r1["CN_TH"].ToString());
                    totalKLCN_QH += r1["CN_QH"].ToString() == "" ? 0 : Convert.ToDouble(r1["CN_QH"].ToString());

                }
                DataRow rKL = dtbBaoHiem.NewRow();
                rKL["STT"] = "";
                rKL["TenDoiTac"] = "B-TỔNG KHÁCH LẺ";
                rKL["DuNoTichLuy"] = totalDuNoTichLuyKL;
                rKL["PhatSinhTuDauThang"] = totalPhatSinhTuDauThangKL;
