                sheet.Cells["A" + index + ":D" + index].Merge = true;
                sheet.Cells["A" + index + ":V" + index].Style.Font.Bold = true;
                sheet.Cells["A" + index + ":D" + index].Style.HorizontalAlignment = ExcelHorizontalAlignment.Right;

                sheet.Cells["A5" + ":V" + index].Style.Border.BorderAround(ExcelBorderStyle.Thin);
                sheet.Cells["A5" + ":V" + index].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":V" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":V" + index].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A5" + ":V" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                sheet.Cells.AutoFitColumns();

                _log4net.End("End C# BCBPTC_CNBHDVChiTiet");
                DateTime end = DateTime.Now;
                this.AddActionLog("Admin", "BCBPTC_CNBHDVChiTiet", "ReportBPTC", start, end, "");
            }
            catch (Exception ex)
            {
                sheet.Cells["A3:A4"].Value = "Lỗi báo cáo" + ex.Message + ". " + ex.InnerException;
                _log4net.Error(ex);
                DateTime end = DateTime.Now;
                this.AddActionLog("Admin", "BCBPTC_CNBHDVChiTiet", "ReportBPTC", start, end, ex);
            }

