        public void ReportBCBPTC_SoatXetChungTu()
        {
            DateTime start = new DateTime();

            var sheet = pck.Workbook.Worksheets["Soat xet chung tu"];

            try
            {
                _log4net.Start("(" + CurrentUser.UserName + ")(" + ShowRoom + ")ReportBCBPTC_SoatXetChungTu");

                DataTable dtbResult = _tkknService.BCBPTC_SoatXetChungTu(ConnectionString, FromDate, ToDate);
                DataTable dtbResultChiTiet = _tkknService.BCBPTC_SoatXetChungTuChiTiet(ConnectionString, FromDate, ToDate);

                Double totalTienMat = 0,
                   totalNganHang = 0,
                   totalTongChi = 0;
                int index = 7;
                foreach (DataRow row in dtbResult.Rows)
                {

                    //neu dong la SUM(A/,B/,...) hoặc SUM1(I/, II/...) thi boi den
                    if (row["Loai"].ToString() == "SUM" || row["Loai"].ToString() == "SUM1")
                    {
                        sheet.Cells["A" + index + ":D" + index].Style.Font.Bold = true;
                    }
                    //khong phai la dong SUM thi moi cong vao phan tong cong o tren tieu de
                    if (row["Loai"].ToString() == "SUM")
                    {
                        totalTienMat += row["ThanhToanTM"].ToString() == "" ? 0 : Convert.ToDouble(row["ThanhToanTM"].ToString());
                        totalNganHang += row["ThanhToanNH"].ToString() == "" ? 0 : Convert.ToDouble(row["ThanhToanNH"].ToString());
                        totalTongChi += row["ThanhToanTong"].ToString() == "" ? 0 : Convert.ToDouble(row["ThanhToanTong"].ToString());
                    }
                    sheet.Cells["A" + index].Value = row["LyDoChi"].ToString().ToUpper();
                    sheet.Cells["B" + index].Value = row["ThanhToanTM"];
                    sheet.Cells["C" + index].Value = row["ThanhToanNH"];
                    sheet.Cells["D" + index].Value = row["ThanhToanTong"];
                    index++;
                }

                sheet.Cells["B" + 6].Value = totalTienMat;
                sheet.Cells["C" + 6].Value = totalNganHang;
                sheet.Cells["D" + 6].Value = totalTongChi;

                //sheet.Cells["A6"].LoadFromDataTable(dtbResult, false);
                string DenNgay = "Từ ngày " + FromDate.ToString("dd/MM/yyyy") + " Đến ngày " + ToDate.ToString("dd/MM/yyyy");
                //phan fromdate và todate
                sheet.Cells["A1"].Value = "BẢNG TỔNG HỢP CÁC KHOẢN CHI " + DenNgay.ToUpper() + " " + ShowRoom;

                //index += 1;
                index = dtbResult.Rows.Count + 6;
                sheet.Cells["A6" + ":D" + index].Style.Border.BorderAround(ExcelBorderStyle.Thin);
                sheet.Cells["A6" + ":D" + index].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A6" + ":D" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A6" + ":D" + index].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A6" + ":D" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                //xuat bang chi tiet ngan hang

                dtbResultChiTiet.DefaultView.RowFilter = "HinhThucThanhToan = 'NH'";
                DataTable tblChiTietNH = dtbResultChiTiet.DefaultView.ToTable();
                index = 7;
                int startRow = 7;
                int endRow = 7;
                string MaCuoiCung = "";
                object SoTienCuoiCung = 0;
                if (tblChiTietNH.Rows.Count > 0)
                {
                    MaCuoiCung = tblChiTietNH.Rows[0]["Ma"].ToString();
                    SoTienCuoiCung = tblChiTietNH.Rows[0]["TongMucChiPhi"];
                }
                foreach (DataRow row in tblChiTietNH.Rows)
                {
                    sheet.Cells["F" + index].Value = index - 6;
                    sheet.Cells["G" + index].Value = row["Ngay"];
                    sheet.Cells["H" + index].Value = row["NoiDung"];
                    sheet.Cells["I" + index].Value = row["SoTien"];
                    sheet.Cells["J" + index].Value = row["Ma"].ToString().ToUpper();
                    //sheet.Cells["K" + index].Value = row["TongMucChiPhi"];
                    sheet.Cells["L" + index].Value = row["NguoiDuyet"];
                    sheet.Cells["M" + index].Value = "";
                    if (MaCuoiCung != row["Ma"].ToString())
                    {
                        //if (startRow != endRow)
                        //{
                        sheet.Cells["J" + startRow + ":J" + endRow].Merge = true;
                        sheet.Cells["K" + startRow + ":K" + endRow].Merge = true;
                        sheet.Cells["K" + startRow].Value = SoTienCuoiCung;
                        startRow = index;
                        MaCuoiCung = row["Ma"].ToString();
                        SoTienCuoiCung = row["TongMucChiPhi"];
                        //}
                    }
                    endRow = index;
                    index++;
                }
                //ghi nhan so tien tong muc thanh toan dong cuoi
                sheet.Cells["K" + startRow].Value = SoTienCuoiCung;


                sheet.Cells["J" + startRow + ":J" + endRow].Merge = true;
                sheet.Cells["K" + startRow + ":K" + endRow].Merge = true;

                sheet.Cells["F" + 6 + ":M" + index].Style.Border.BorderAround(ExcelBorderStyle.Thin);
                sheet.Cells["F" + 6 + ":M" + index].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                sheet.Cells["F" + 6 + ":M" + index].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["F" + 6 + ":M" + index].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                sheet.Cells["F" + 6 + ":M" + index].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                //phan thanh toan tien mat

                //copy dong tieu de tu phần ngân hàng xuống phần tiền mặt
                index++;

                sheet.Cells["F4:M6"].Copy(sheet.Cells["F" + index]);

                index += 3;

                sheet.Cells["F" + (index - 3)].Value = "CHI TIỀN MẶT";


                dtbResultChiTiet.DefaultView.RowFilter = "HinhThucThanhToan = 'TM'";
                DataTable tblChiTietTM = dtbResultChiTiet.DefaultView.ToTable();
                int index2 = index;
                startRow = index2;
                endRow = index2;
                MaCuoiCung = "";
                if (tblChiTietTM.Rows.Count > 0)
                {
                    MaCuoiCung = tblChiTietTM.Rows[0]["Ma"].ToString();
                    SoTienCuoiCung = tblChiTietTM.Rows[0]["TongMucChiPhi"];
                }
                foreach (DataRow row in tblChiTietTM.Rows)
                {
                    sheet.Cells["F" + index2].Value = index2 - index + 1;
                    sheet.Cells["G" + index2].Value = row["Ngay"];
                    sheet.Cells["H" + index2].Value = row["NoiDung"];
                    sheet.Cells["I" + index2].Value = row["SoTien"];
                    sheet.Cells["J" + index2].Value = row["Ma"].ToString().ToUpper();
                    // sheet.Cells["K" + index2].Value = row["TongMucChiPhi"];
                    sheet.Cells["L" + index2].Value = row["NguoiDuyet"];
                    sheet.Cells["M" + index2].Value = "";
                    if (MaCuoiCung != row["Ma"].ToString())
                    {
                        //if (startRow != endRow)
                        //{
                        sheet.Cells["J" + startRow + ":J" + endRow].Merge = true;
                        sheet.Cells["K" + startRow + ":K" + endRow].Merge = true;
                        sheet.Cells["K" + startRow].Value = SoTienCuoiCung;
                        startRow = index2;
                        MaCuoiCung = row["Ma"].ToString();
                        SoTienCuoiCung = row["TongMucChiPhi"];
                        //}
                    }
                    endRow = index2;
                    index2++;
                }
                //ghi nhan so tien tong muc thanh toan dong cuoi
                sheet.Cells["K" + startRow].Value = SoTienCuoiCung;

                sheet.Cells["J" + startRow + ":J" + endRow].Merge = true;
                sheet.Cells["K" + startRow + ":K" + endRow].Merge = true;
                index2--;
                sheet.Cells["F" + index + ":M" + index2].Style.Border.BorderAround(ExcelBorderStyle.Thin);
                sheet.Cells["F" + index + ":M" + index2].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                sheet.Cells["F" + index + ":M" + index2].Style.Border.Right.Style = ExcelBorderStyle.Thin;
