        /// <summary>
        /// Export excel Von Luu Dong
        /// </summary>
        /// <param name="FromDate"></param>
        /// <param name="ToDate"></param>
        /// <returns></returns>
        public ActionResult ReportAll_BPTC_VLD(DateTime FromDate, DateTime ToDate)
        {
            try
            {
                this.FromDate = FromDate;
                this.ToDate = ToDate;
                //var str = CacheKey.keyExcelTotal
                TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year;
                TuNgayDenNgay += " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                DenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;

                string str = Server.MapPath("~\\Views\\FileMau\\Template_BaoCaoPTC_VLD.xlsx");
                FileInfo template = new FileInfo(str);
                pck = new ExcelPackage(new FileInfo(str));

                string strFileName = "Bao_cao_Von_Luu_Dong" + FromDate.ToString("dd.MM.yyyy") + "_" + ToDate.ToString("dd.MM.yyyy") + "_" + DateTime.Now.ToString("hhMMssfff") + ".xlsx";



                #region Sheet DATA
                DataSet dsData = _tkknService.BCBPTC_VLD_Data(ConnectionString, FromDate, ToDate);
                //sheet Thu chi
                pck.Workbook.Worksheets["DATA"].Cells["A2"].Value = "Ngày báo cáo " + FromDate.ToString("dd/MM/yyyy") + "-" + ToDate.ToString("dd/MM/yyyy");
                pck.Workbook.Worksheets["DATA"].Cells["A11"].LoadFromDataTable(dsData.Tables[0], false);
                pck.Workbook.Worksheets["DATA"].Cells["A18"].LoadFromDataTable(dsData.Tables[1], false);
                //cac phan lien quan TNK
                if (dsData.Tables.Count > 2)
                    pck.Workbook.Worksheets["DATA"].Cells["AO11"].LoadFromDataTable(dsData.Tables[2], false);
                #endregion Sheet DATA

                #region Sheet TH THU - CHI
                DataSet dsThuChi = _tkknService.BCBPTC_VLD_ThuChi(ConnectionString, FromDate, ToDate);
                //sheet Thu chi
                pck.Workbook.Worksheets["TH THU- CHI"].Cells["A5"].Value = "Ngày báo cáo " + FromDate.ToString("dd/MM/yyyy") + "-" + ToDate.ToString("dd/MM/yyyy");
                pck.Workbook.Worksheets["TH THU- CHI"].Cells["A11"].LoadFromDataTable(dsThuChi.Tables[0], false);
                pck.Workbook.Worksheets["TH THU- CHI"].Cells["A26"].LoadFromDataTable(dsThuChi.Tables[1], false);

                #endregion Sheet TH THU - CHI


                return new ExcelInsuranceDownload(pck, strFileName);
            }
            catch (Exception ex)
            {
                _logger.WriteLog("ReportAll_BPTC_VLD", ex);
                _log4net.Error(ex);
                //return ex.Message;
            }
            return View();
        }


