        //BC Hoa hồng bảo hiểm thu hộ
        public ActionResult BCHHBHTH(DateTime FromDate, DateTime ToDate)
        {
            DataTable data = new DataTable();
            try
            {
                data = _tkknService.BCHHBHTH(FromDate, ToDate, "NTHBH");
                TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                List<string> listColumnName = new List<string>();
                if (data.Rows.Count > 0)
                {
                    foreach (DataColumn column in data.Columns)
                    {
                        listColumnName.Add(column.ToString());
                    }
                }
                ViewBag.ListHeader = listColumnName;
                ViewBag.CountColumns = listColumnName.Count;
                ViewBag.CountData = data.Rows.Count;
                ViewBag.Data = data;
                ViewBag.ToDate = TuNgayDenNgay;
            }
            catch (Exception ex)
            {
                log.Error(ex);
                TempData["Error"] = ex;
            }
            return PartialView(data);
        }

        //Xuất excel hoa hồng BHTH
        public void ReportBC_HHBHTH()
        {
            var sheet = pck.Workbook.Worksheets["Hoa Hồng BHTH"];
            var dt = _tkknService.BCHHBHTH(FromDate, ToDate, "NTHBH");
            sheet.Cells[2, 1, 2, 4].Value = DenNgay;
            var cell_fillData = sheet.Cells[5, 1, dt.Rows.Count + 4, dt.Columns.Count];
            var cell_total = sheet.Cells[dt.Rows.Count + 4, 1, dt.Rows.Count + 4, dt.Columns.Count];
            cell_fillData.LoadFromDataTable(dt, false);
