            List<string> lstColumn = new List<string>() { "STT", "NgayThu", "MaPhieuThu", "Hoten", "SoHopDong", "BienSo",
            "SoChungTu", "TenDoiTac", "GiaVon","GiamGia","ChuyenCoc", "TM_NH",  "TongCong", "SoTienThu", "HoaHong"};
            for (int i = 0; i < lstColumn.Count; i++)
            {
                dtbKL.Columns[lstColumn[i]].SetOrdinal(i);
            }
            for (int i = dtbKL.Columns.Count - 1; i >= lstColumn.Count; i--)
            {
                dtbKL.Columns.RemoveAt(i);
            }
            int stt = 1;
            double TongGiaBan = 0,
                       TongThucThu = 0,
                       TongGiamGia = 0,
                       TongThanhToan = 0,
                       TongHoaHong = 0,
                       TongChuyenCoc = 0,
                       TongTM_NH = 0;
            foreach (DataRow row in dtbKL.Rows)
            {
                row["STT"] = stt;
                TongGiaBan += row["GiaVon"].ToString() == "" ? 0 : Convert.ToDouble(row["GiaVon"]);
                TongGiamGia += row["GiamGia"].ToString() == "" ? 0 : Convert.ToDouble(row["GiamGia"]);
                TongThucThu += row["TongCong"].ToString() == "" ? 0 : Convert.ToDouble(row["TongCong"]);
                TongThanhToan += row["SoTienThu"].ToString() == "" ? 0 : Convert.ToDouble(row["SoTienThu"]);
                TongHoaHong += row["HoaHong"].ToString() == "" ? 0 : Convert.ToDouble(row["HoaHong"]);
                TongChuyenCoc += row["ChuyenCoc"].ToString() == "" ? 0 : Convert.ToDouble(row["ChuyenCoc"]);
                TongTM_NH += row["TM_NH"].ToString() == "" ? 0 : Convert.ToDouble(row["TM_NH"]);
