            dr1["STT"] = "TỔNG";
            dr1["GiaVon"] = TongGiaBan;
            dr1["GiamGia"] = TongGiamGia;
            dr1["TongCong"] = TongThucThu;
            dr1["SoTienThu"] = TongThanhToan;
            dr1["HoaHong"] = TongHoaHong;
            dr1["ChuyenCoc"] = TongChuyenCoc;
            dr1["TM_NH"] = TongTM_NH;
            dtbKL.Rows.Add(dr1);
            //-------------------------------------------------------------------------------------------------------
            //KM 
            for (int i = 0; i < lstColumn.Count; i++)
            {
                dtbKM.Columns[lstColumn[i]].SetOrdinal(i);
            }
            for (int i = dtbKM.Columns.Count - 1; i >= lstColumn.Count; i--)
            {
                dtbKM.Columns.RemoveAt(i);
            }
            stt = 1;
            double TongGiaBanKM = 0,
                       TongThucThuKM = 0,
                       TongGiamGiaKM = 0,
                       TongThanhToanKM = 0,
                       TongHoaHongKM = 0,
                      TongChuyenCocKM = 0,
                      TongTM_NHKM = 0;
            foreach (DataRow row in dtbKM.Rows)
            {
