                TongGiamGiaKM += row["GiamGia"].ToString() == "" ? 0 : Convert.ToDouble(row["GiamGia"]);
                TongThucThuKM += row["TongCong"].ToString() == "" ? 0 : Convert.ToDouble(row["TongCong"]);
                TongThanhToanKM += row["SoTienThu"].ToString() == "" ? 0 : Convert.ToDouble(row["SoTienThu"]);
                TongHoaHongKM += row["HoaHong"].ToString() == "" ? 0 : Convert.ToDouble(row["HoaHong"]);
                TongChuyenCocKM += row["ChuyenCoc"].ToString() == "" ? 0 : Convert.ToDouble(row["ChuyenCoc"]);
                TongTM_NHKM += row["TM_NH"].ToString() == "" ? 0 : Convert.ToDouble(row["TM_NH"]);
                stt++;
            }
            //TỔNG 
            DataRow dr2 = dtbKM.NewRow();
            dr2["STT"] = "TỔNG";
            dr2["GiaVon"] = TongGiaBanKM;
            dr2["GiamGia"] = TongGiamGiaKM;
            dr2["TongCong"] = TongThucThuKM;
            dr2["SoTienThu"] = TongThanhToanKM;
            dr2["HoaHong"] = TongHoaHongKM;
            dr2["ChuyenCoc"] = TongChuyenCocKM;
            dr2["TM_NH"] = TongTM_NHKM;
            dtbKM.Rows.Add(dr2);
            //TỔNG CỘNG
            DataRow dr3 = dtbKM.NewRow();
            dr3["STT"] = "TỔNG CỘNG";
            dr3["GiaVon"] = TongGiaBan + TongGiaBanKM;
            dr3["GiamGia"] = TongGiamGia + TongGiamGiaKM;
            dr3["TongCong"] = TongThucThu + TongThucThuKM;
            dr3["SoTienThu"] = TongThanhToan + TongThanhToanKM;
            dr3["HoaHong"] = TongHoaHong + TongHoaHongKM;
            dr3["ChuyenCoc"] = TongChuyenCoc + TongChuyenCocKM;
            dr3["TM_NH"] = TongTM_NH + TongTM_NHKM;
            dtbKM.Rows.Add(dr3);
            #endregion
            //-------------------------------------------------------------------------------------------------------
            #region Phần Excel
            var sheet = pck.Workbook.Worksheets["DTHU GHBH"];

            int idx = 0;
            sheet.View.FreezePanes(5, 1);
            Color colorSum = System.Drawing.ColorTranslator.FromHtml("#DEB887");
            //LoadDatatable KL
            sheet.InsertRow(4, dtbKL.Rows.Count);
