                sheet.Cells[4, 1, idx, dtbKM.Columns.Count].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells[4, 1, idx, dtbKM.Columns.Count].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

            }
            //LoadDatatable KM
            idx = idx + 2;
            if (dtbKM != null && dtbKM.Rows.Count > 0)
            {
                sheet.Cells[idx, 1].LoadFromDataTable(dtbKM, false);
                int sidx = idx;
                idx = idx + dtbKM.Rows.Count - 2;
                sheet.Cells[idx, 1, idx, 8].Merge = true;
                sheet.Cells[idx, 1, idx, dtbKM.Columns.Count].Style.Font.Bold = true;

                idx = idx + 1;
                sheet.Cells["A" + idx + ":H" + idx].Merge = true;
                sheet.Cells["A" + idx + ":O" + idx].Style.Font.Bold = true;
                sheet.Cells["A" + idx + ":O" + idx].Style.Fill.PatternType = ExcelFillStyle.Solid;
                sheet.Cells["A" + idx + ":O" + idx].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.Yellow);
                sheet.Cells["A" + idx + ":O" + idx].Style.Fill.PatternType = ExcelFillStyle.Solid;
                sheet.Cells["A" + idx + ":O" + idx].Style.Font.Color.SetColor(System.Drawing.Color.Red);

                sheet.Cells["I" + sidx + ":O" + idx].Style.Numberformat.Format = format;
                sheet.Cells["A" + sidx + ":O" + idx].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells["A" + sidx + ":O" + idx].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
            }

            #endregion
        }
