                    TongThuHH_ConLai += row["ThuHH_ConLai"].ToString() == "" ? 0 : Convert.ToDouble(row["ThuHH_ConLai"]);
                    stt++;
                }
                DataRow dr = data.NewRow();
                dr["TenDoiTac"] = "TỔNG";
                dr["ThuHo_SoTienNo"] = TongThuHo_SoTienNo;
                dr["ThuHo_DaTra"] = TongThuHo_DaTra;
                dr["ThuHo_ConLai"] = TongThuHo_ConLai;
                dr["ThuHH_SoTienNo"] = TongThuHH_SoTienNo;
                dr["ThuHH_DaTra"] = TongThuHH_DaTra;
                dr["ThuHH_ConLai"] = TongThuHH_ConLai;
                data.Rows.Add(dr);

                ViewBag.ListHeader = listColumnName;
                ViewBag.CountColumns = listColumnName.Count;
                ViewBag.CountData = data.Rows.Count;
                ViewBag.Data = data;
                ViewBag.ToDate = TuNgayDenNgay;
            }
            catch (Exception ex)
            {
                log.Error(ex);
                TempData["Error"] = ex;
            }
            return PartialView(data);
        }
        //Xuất excel hoa hồng BHTH
        public void ReportBC_HHKMGHBH()
        {
            var sheet = pck.Workbook.Worksheets["Hoa Hồng KMGHBH"];
            //var dt = _tkknService.BCHHBHTH(FromDate, ToDate, "NTHBH");
            DataTable dtbResult = _tkknService.BCChiTietHHGHBH(ConnectionString, FromDate, ToDate);
            DataView dvResultKL = dtbResult.DefaultView;
            dvResultKL.RowFilter = "LoaiPhieuNo = 'k1GHB'";
            var dt = dvResultKL.ToTable();
            double TongThuHo_SoTienNo = 0, TongThuHo_DaTra = 0, TongThuHo_ConLai = 0, TongThuHH_SoTienNo = 0, TongThuHH_DaTra = 0, TongThuHH_ConLai = 0;
            int stt = 1;
            foreach (DataRow row in dt.Rows)
            {
                row["STT"] = stt;
                TongThuHo_SoTienNo += row["ThuHo_SoTienNo"].ToString() == "" ? 0 : Convert.ToDouble(row["ThuHo_SoTienNo"]);
                TongThuHo_DaTra += row["ThuHo_DaTra"].ToString() == "" ? 0 : Convert.ToDouble(row["ThuHo_DaTra"]);
                TongThuHo_ConLai += row["ThuHo_ConLai"].ToString() == "" ? 0 : Convert.ToDouble(row["ThuHo_ConLai"]);
                TongThuHH_SoTienNo += row["ThuHH_SoTienNo"].ToString() == "" ? 0 : Convert.ToDouble(row["ThuHH_SoTienNo"]);
                TongThuHH_DaTra += row["ThuHH_DaTra"].ToString() == "" ? 0 : Convert.ToDouble(row["ThuHH_DaTra"]);
                TongThuHH_ConLai += row["ThuHH_ConLai"].ToString() == "" ? 0 : Convert.ToDouble(row["ThuHH_ConLai"]);
                stt++;
            }
            DataRow dr = dt.NewRow();
            dr["TenDoiTac"] = "TỔNG";
            dr["ThuHo_SoTienNo"] = TongThuHo_SoTienNo;
            dr["ThuHo_DaTra"] = TongThuHo_DaTra;
            dr["ThuHo_ConLai"] = TongThuHo_ConLai;
            dr["ThuHH_SoTienNo"] = TongThuHH_SoTienNo;
            dr["ThuHH_DaTra"] = TongThuHH_DaTra;
            dr["ThuHH_ConLai"] = TongThuHH_ConLai;
            dt.Rows.Add(dr);
            sheet.Cells[2, 1, 2, 4].Value = DenNgay;
            var cell_fillData = sheet.Cells[5, 1, dt.Rows.Count + 4, dt.Columns.Count];
            var cell_total = sheet.Cells[dt.Rows.Count + 4, 1, dt.Rows.Count + 4, dt.Columns.Count];
            cell_fillData.LoadFromDataTable(dt, false);
            cell_fillData.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
            cell_fillData.Style.Border.Right.Style = ExcelBorderStyle.Thin;
            cell_fillData.Style.Border.Left.Style = ExcelBorderStyle.Thin;
            sheet.Cells[5, 6, dt.Rows.Count + 4, dt.Columns.Count].Style.Numberformat.Format = "#,##0";
            cell_fillData.AutoFitColumns();

            Color colFromHex = System.Drawing.ColorTranslator.FromHtml("#ffff00");
            cell_total.Style.Fill.PatternType = ExcelFillStyle.Solid;
            cell_total.Style.Fill.BackgroundColor.SetColor(colFromHex);
            cell_total.Style.Font.Bold = true;
        }
