        public ActionResult BCXeLoiNhuan(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbCash = _tkknService.BCNgayXeLoiNhuan(ConnectionString, FromDate, ToDate);
            DataView dtvGXC = dtbCash.DefaultView;
            dtvGXC.RowFilter = "LoaiThanhToan = 'GIAO_XE_COC'";
            DataTable dtbGXC = dtvGXC.ToTable();

            DataView dtvGXN = dtbCash.DefaultView;
            dtvGXN.RowFilter = "LoaiThanhToan = 'GIAO_XE_NGAY'";
            DataTable dtbGXN = dtvGXN.ToTable();
            //Phần giao xe đại lý
            DataView dtvGXDL = dtbCash.DefaultView;
            dtvGXDL.RowFilter = "LoaiThanhToan = 'GIAO_XE_DAI_LY'";
            DataTable dtbGXDL = dtvGXDL.ToTable();
            //phần trao đổi xe
            DataView dtvTDX = dtbCash.DefaultView;
            dtvTDX.RowFilter = "LoaiThanhToan = 'TRAO_DOI_XE'";
            DataTable dtbTDX = dtvTDX.ToTable();
            //phần về TSCD
            DataView dtvTSCD = dtbCash.DefaultView;
            dtvTSCD.RowFilter = "LoaiThanhToan = 'TSCD'";
            DataTable dtbTSCD = dtvTSCD.ToTable();
            //phần về ONLINE
            DataView dtvOnline = dtbCash.DefaultView;
            dtvOnline.RowFilter = "LoaiThanhToan = 'ONLINE'";
            DataTable dtbOnline = dtvOnline.ToTable();
            //Giao xe cũ
            DataView dtvGiaoXeCu = dtbCash.DefaultView;
            dtvGiaoXeCu.RowFilter = "LoaiThanhToan = 'XE_CU'";
            DataTable dtbGiaoXeCu = dtvGiaoXeCu.ToTable();

            //phan truc them kho xe
            DataTable dtbBCKhoXe = _tkknService.dtbBCKhoXe(ConnectionString, FromDate, ToDate);
            DataView dtvBCKhoXe = dtbBCKhoXe.DefaultView;
