        public ActionResult BCQuanLyXePTC(DateTime ToDate)
        {
            TuNgayDenNgay = "Ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
            ViewBag.TuNgayDenNgay = TuNgayDenNgay;
            DataTable data = _tkknService.BCQuanLyXePTC(ToDate);
            //total tondaungay
            ViewBag.TotalTonXeDauNgay = Convert.ToDouble(data.Compute("SUM(TonXeNgoaiDauNgay)", string.Empty));
            ViewBag.TotalTonXeToyotaDauNgay = Convert.ToDouble(data.Compute("SUM(TonXeToyotaDauNgay)", string.Empty));
            ViewBag.TotalThanhTienDauNgay = Convert.ToDouble(data.Compute("SUM(ThanhTienDauNgay)", string.Empty));
            //total nhap trong ngay
            ViewBag.TotalNhapNgoaiTrongNgay = Convert.ToDouble(data.Compute("SUM(SLNhapNgoaiTrongNgay)", string.Empty));
            ViewBag.TotalSLNhapToyotaTrongNgay = Convert.ToDouble(data.Compute("SUM(SLNhapToyotaTrongNgay)", string.Empty));
            ViewBag.TotalTongGiaTriNhap = Convert.ToDouble(data.Compute("SUM(TongGiaTriNhap)", string.Empty));

            ViewBag.TotalSLNhapLuyKeXeNgoai = Convert.ToDouble(data.Compute("SUM(SLNhapLuyKeXeNgoai)", string.Empty));
            ViewBag.TotalSLNhapLuyKeXeToyota = Convert.ToDouble(data.Compute("SUM(SLNhapLuyKeXeToyota)", string.Empty));
            ViewBag.TotalTongGiaTriNhapLuyKe = Convert.ToDouble(data.Compute("SUM(TongGiaTriNhapLuyKe)", string.Empty));
            //total xuat trong ngay
            ViewBag.TotalSLXuatNgoaiTrongNgay = Convert.ToDouble(data.Compute("SUM(SLXuatNgoaiTrongNgay)", string.Empty));
            ViewBag.TotalSLXuatToyotaTrongNgay = Convert.ToDouble(data.Compute("SUM(SLXuatToyotaTrongNgay)", string.Empty));
            ViewBag.TotalTongGiaTriXuat = Convert.ToDouble(data.Compute("SUM(TongGiaTriXuat)", string.Empty));

            ViewBag.TotalSLXuatLuyKeXeNgoai = Convert.ToDouble(data.Compute("SUM(SLXuatLuyKeXeNgoai)", string.Empty));
            ViewBag.TotalSLXuatLuyKeXeToyota = Convert.ToDouble(data.Compute("SUM(SLXuatLuyKeXeToyota)", string.Empty));
            ViewBag.TotalTongGiaTriXuatLuyKe = Convert.ToDouble(data.Compute("SUM(TongGiaTriXuatLuyKe)", string.Empty));

            //total ton cuoi ngay
            ViewBag.TotalTonXeNgoaiCuoiNgay = Convert.ToDouble(data.Compute("SUM(TonXeNgoaiCuoiNgay)", string.Empty));
            ViewBag.TotalTonXeToyotaCuoiNgay = Convert.ToDouble(data.Compute("SUM(TonXeToyotaCuoiNgay)", string.Empty));
            ViewBag.TotalThanhTienCuoiNgay = Convert.ToDouble(data.Compute("SUM(ThanhTienCuoiNgay)", string.Empty));

            //total tong coc+  khac
            DataRow dt = data.Rows[0];
            ViewBag.TotalTongCoc = dt["TongCoc"];
            ViewBag.TotalNoNHChuaGiaiNgan = dt["NoNHChuaGiaiNgan"];
            #region total NoNHChuaGiaiNgan theo group
            //var items = data.AsEnumerable().GroupBy(r => new { LoaiXe = r["LoaiXe"], CodeMau = r["CodeMau"],NoNH=r["NoNHChuaGiaiNgan"] })
            //                .ToArray().Select(s=>s.Key).Select(s=>double.Parse(s.NoNH.ToString())).ToList();
            //ViewBag.TotalNoNHChuaGiaiNgan = Convert.ToDouble(items.Sum());
            #endregion
            ViewBag.TotalSLTheChap = Convert.ToDouble(data.Compute("SUM(SLTheChap)", string.Empty));
            ViewBag.TotalGiaTriTheChap = Convert.ToDouble(data.Compute("SUM(GiaTriTheChap)", string.Empty));
            try
            {
                return PartialView(data);
            }
            catch (Exception)
            {
                return PartialView(null);
                throw;
            }
        }
