        public void ReportKMHuaTang()
        {
            try
            {
                DataTableCollection data = _tkknService.BCKM_HuaTang(ConnectionString, FromDate, ToDate);
                var sheet = pck.Workbook.Worksheets["Nợ phải trả KM hứa tặng"];
                // Create Excel EPPlus Package based on template stream
                int rowIndex = 4;
                int startColum = 1;
                //header
                sheet.Cells["A2"].Value = string.Format("Đến ngày {0}", ToDate.ToString("dd/MM/yyyy"));
                var range = sheet.Cells[rowIndex, startColum].LoadFromDataTable(data[0], false);
                DataTable dt = data[0];
