                sheet.Cells[3 + dt.Rows.Count, 3, 8 + dt.Rows.Count, 3].Style.Font.Bold = true;

                sheet.Cells[5 + dt.Rows.Count, 4].Value = dtTH.Rows[0]["NoDauKy"];
                sheet.Cells[6 + dt.Rows.Count, 4].Value = dtTH.Rows[0]["PSNo"];
                sheet.Cells[7 + dt.Rows.Count, 4].Value = dtTH.Rows[0]["DaTraTrongKy"];
                sheet.Cells[8 + dt.Rows.Count, 4].Value = dtTH.Rows[0]["CuoiKy"];

                sheet.Cells[5 + dt.Rows.Count, 3, 8 + dt.Rows.Count, 4].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                sheet.Cells[5 + dt.Rows.Count, 3, 8 + dt.Rows.Count, 4].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                sheet.Cells[5 + dt.Rows.Count, 3, 8 + dt.Rows.Count, 4].Style.Border.Left.Style = ExcelBorderStyle.Thin;

                sheet.Cells[4, 1, (9 + dt.Rows.Count) - 1, dt.Columns.Count].Style.Numberformat.Format = "#,##0";
            }
