        #region Nợ hoa hồng tài xế
        public ActionResult BCNoHHTaiXe(DateTime FromDate, DateTime ToDate)
        {
            DataTable data = new DataTable();
            try
            {
                data = _tkknService.BCNoHHTaiXe(ConnectionString, FromDate, ToDate);
                TuNgayDenNgay = "Từ ngày " + FromDate.Day + "/" + FromDate.Month + "/" + FromDate.Year +
                    " đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                List<string> listColumnName = new List<string>();
                if (data.Rows.Count > 0)
                {
                    foreach (DataColumn column in data.Columns)
                    {
                        listColumnName.Add(column.ToString());
                    }
                }
                ViewBag.ListHeader = listColumnName;
                ViewBag.CountColumns = listColumnName.Count;
                ViewBag.CountData = data.Rows.Count;
                ViewBag.Data = data;
                ViewBag.ToDate = TuNgayDenNgay;
            }
            catch (Exception ex)
            {
                log.Error(ex);
                TempData["Error"] = ex;
            }
            return PartialView(data);
        }
