                Color colorSum = System.Drawing.ColorTranslator.FromHtml("#DEB887");
                try
                {
                    sheet.Cells["A1:H1"].Value = "DANH SÁCH CHI TIẾT CÔNG NỢ PHẢI THU THƯỞNG THÀNH TÍCH BÁN HÀNG " + ShowRoom;
                    sheet.Cells["A2:H2"].Value = TuNgayDenNgay;
                    sheet.Cells["A4"].LoadFromDataTable(dtbResult, false);
                    sheet.Cells["A4" + ":M" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":M" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":M" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":M" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

