                        sheet.Cells["A" + col + ":F" + col].Merge = true;
                        sheet.Cells["A" + col + ":M" + col].Style.Fill.PatternType = ExcelFillStyle.Solid;
                        sheet.Cells["A" + col + ":M" + col].Style.Fill.BackgroundColor.SetColor(colorSum);
