        public void Report_ThuChiHo()
        {
            try
            {

                DataTableCollection dtbResult = _tkknService.BCNgayThuChiHo(ConnectionString, FromDate, ToDate);
                ViewBag.FromDate = FromDate;
                ViewBag.ToDate = ToDate;
                TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                ViewBag.TuNgayDenNgay = TuNgayDenNgay;

                DataTable dtDSChiHo = dtbResult[0];
                List<int> lstsumrow = new List<int>();
                lstsumrow.Add(dtDSChiHo.Rows.Count - 1);


                //phần excel
                var sheet = pck.Workbook.Worksheets["CHI HỘ-THU HỘ"];
                sheet.InsertRow(5, dtDSChiHo.Rows.Count - 2);
                Color colorSum = System.Drawing.ColorTranslator.FromHtml("#DEB887");
                try
                {
                    sheet.Cells["A2:J2"].Value = TuNgayDenNgay;
                    sheet.Cells["A4"].LoadFromDataTable(dtDSChiHo, false);
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":K" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["C4:M" + (lstsumrow[lstsumrow.Count - 1] + 5)].Style.Numberformat.Format = format;

                    foreach (int idex in lstsumrow)
                    {
                        int col = idex + 4;
                        sheet.Cells["A" + col].Value = "TỔNG CỘNG";
                    }

                    DataTable dtDSTra = dtbResult[1];
                    int lastRow = dtDSChiHo.Rows.Count + 7;
                    sheet.InsertRow(lastRow, dtDSTra.Rows.Count - 2);
                    sheet.Cells["A" + lastRow].LoadFromDataTable(dtDSTra, false);
                    sheet.Cells["A" + lastRow + ":E" + (dtDSTra.Rows.Count - 2 + lastRow)].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A" + lastRow + ":E" + (dtDSTra.Rows.Count - 2 + lastRow)].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A" + lastRow + ":E" + (dtDSTra.Rows.Count - 2 + lastRow)].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A" + lastRow + ":E" + (dtDSTra.Rows.Count - 2 + lastRow)].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["B" + lastRow + ":E" + (dtDSTra.Rows.Count - 1 + lastRow)].Style.Numberformat.Format = format;
                }
                catch (Exception ex)
                {
                    sheet.Cells["A3:A4"].Value = "Lỗi báo cáo" + ex.Message + ". " + ex.InnerException;
                    _log4net.Error(ex);
                }
            }
            catch (Exception ex)
            {
                log.Error(ex);
            }
        }
