        public void ReportBCKHCDT()
        {
            try
            {

                DataTable dtbResult = _tkknService.BCKHCDT(ConnectionString, FromDate, ToDate);
                ViewBag.FromDate = FromDate;
                ViewBag.ToDate = ToDate;
                TuNgayDenNgay = "Đến ngày " + ToDate.Day + "/" + ToDate.Month + "/" + ToDate.Year;
                ViewBag.TuNgayDenNgay = TuNgayDenNgay;

                string KH = "";
                KH = dtbResult.Rows[0]["DienGiai"].ToString();
                List<int> lstsumrow = new List<int>();
                int i = 1;
                while (i < dtbResult.Rows.Count)
                {

                    if (KH != dtbResult.Rows[i]["DienGiai"].ToString())
                    {
                        lstsumrow.Add(i);
                        i = i + 2;
                    }
                    else
                    {
                        KH = dtbResult.Rows[i]["DienGiai"].ToString();
                        i++;
                    }
                    //else
                    //    KH = dtbResult.Rows[i]["DienGiai"].ToString();
                }
                lstsumrow.Add(dtbResult.Rows.Count - 1);
                List<string> lstcol = new List<string>() { "STT", "NgayNo", "TenDoiTac", "GhiChu", "SoTienNo", "SoTienDaTra", "SoTienConLai", "NgayThanhToan" };
                for (i = 0; i < lstcol.Count; i++)
                {
                    dtbResult.Columns[lstcol[i]].SetOrdinal(i);
                }
                for (i = dtbResult.Columns.Count - 1; i >= lstcol.Count; i--)
                {
                    dtbResult.Columns.RemoveAt(i);
                }
                //phần excel
                var sheet = pck.Workbook.Worksheets["KHCĐT"];
                sheet.View.FreezePanes(5, 1);
                Color colorSum = System.Drawing.ColorTranslator.FromHtml("#DEB887");
                try
                {
                    sheet.Cells["A1:H1"].Value = "DANH SÁCH CHI TIẾT CÔNG NỢ KHCĐT " + ShowRoom;
                    sheet.Cells["A2:H2"].Value = TuNgayDenNgay;
                    sheet.Cells["A4"].LoadFromDataTable(dtbResult, false);
                    sheet.Cells["A4" + ":H" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Left.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":H" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Right.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":H" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Top.Style = ExcelBorderStyle.Thin;
                    sheet.Cells["A4" + ":H" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Border.Bottom.Style = ExcelBorderStyle.Thin;

                    sheet.Cells["E4:G" + (lstsumrow[lstsumrow.Count - 1] + 4)].Style.Numberformat.Format = format;
                    foreach (int idex in lstsumrow)
                    {
                        int col = idex + 4;
                        sheet.Cells["A" + col + ":D" + col].Merge = true;
                        sheet.Cells["A" + col + ":H" + col].Style.Fill.PatternType = ExcelFillStyle.Solid;
                        sheet.Cells["A" + col + ":H" + col].Style.Fill.BackgroundColor.SetColor(colorSum);
                        sheet.Cells["A" + col + ":H" + col].Style.Font.Bold = true;
                    }
                }
                catch (Exception ex)
                {
                    sheet.Cells["A3:A4"].Value = "Lỗi báo cáo" + ex.Message + ". " + ex.InnerException;
                    _log4net.Error(ex);
                }
            }
            catch (Exception ex)
            {
                log.Error(ex);
            }
        }
