        public ActionResult ReportLoiNhuanExcel(DateTime FromDate, DateTime ToDate)
        {
            DataTable dtbResult = _tkknService.BCLoiNhuanPTC(ConnectionString, FromDate, ToDate);
            string templatePath = Server.MapPath("~/Views/FileMau/Template_BaoCaoLoiNhuanPTC.xlsx");

            byte[] result;

            using (var pck = new ExcelPackage(new FileInfo(templatePath)))
            {
                var ws = pck.Workbook.Worksheets.FirstOrDefault();
                ws.Cells[2, 1].LoadFromDataTable(dtbResult, false);

                var dataRange = ws.Cells[2, 1, dtbResult.Rows.Count + 1, dtbResult.Columns.Count]; // +1 nếu hàng tiêu đề ở dòng 1

                // 🔹 Thêm border 4 cạnh (mảnh vừa phải)
                dataRange.Style.Border.Top.Style = OfficeOpenXml.Style.ExcelBorderStyle.Thin;
                dataRange.Style.Border.Bottom.Style = OfficeOpenXml.Style.ExcelBorderStyle.Thin;
                dataRange.Style.Border.Left.Style = OfficeOpenXml.Style.ExcelBorderStyle.Thin;
                dataRange.Style.Border.Right.Style = OfficeOpenXml.Style.ExcelBorderStyle.Thin;

                result = pck.GetAsByteArray();
            }
            Response.Cookies.Add(new HttpCookie("fileDownload", "true")
            {
                Path = "/"
            });
            // ✅ pck đã dispose xong, nhưng mình đã có mảng byte => an toàn
            return File(result,
                "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                "BaoCaoLoiNhuanPTC.xlsx");
        }

